 banks[ch].append(dict(id=f'c{ch}-q{n:03}',chapter=ch,slides=slide if isinstance(slide,list) else [slide],theme=theme,difficulty=level,type=kind,prompt=prompt,options=opts,answer=[str(i) for i in correct],explanation=why,code=code,essential=level=='facile'))
