Q(2,5,'Visibilité','Quelles zones peuvent accéder directement à une propriété protected ?', [('La classe qui la déclare','L’accès interne est autorisé.'),('Ses classes filles','protected permet l’accès dans les classes dérivées.'),('Tout script extérieur','Ce serait public.'),('Uniquement le navigateur','La visibilité est une règle du langage PHP côté serveur.')],'protected ouvre l’accès à la hiérarchie, pas au code extérieur.','facile',[0,1],'multiple')
Q(2,7,'Encapsulation','Quel est le rôle de setNum($nvNum) ?', [('Modifier le numéro de l’objet','Le setter affecte le paramètre à $this->num.'),('Renvoyer nécessairement le numéro','C’est le rôle du getter montré.'),('Créer une classe','Une classe est déclarée avec class.'),('Détruire l’objet','Le destructeur est __destruct.')],'Un setter est une méthode de modification.','facile')
Q(2,7,'Encapsulation','Quel corps convient à getNum() ?', [('return $this->num;','Il renvoie la propriété de l’instance courante.'),('return $num;','$num serait une variable locale distincte.'),('echo $this->num;','Cela affiche au lieu de renvoyer.'),('$this->num = 0;','Cela modifie la propriété sans la retourner.')],'Un getter renvoie la valeur de l’attribut.','facile')
Q(2,8,'Instance','Que représente $this dans une méthode d’instance ?', [('L’objet courant','Il donne accès aux membres de cette instance.'),('La classe mère uniquement','La mère se désigne notamment par parent.'),('Une variable globale de connexion','Aucun rapport avec une connexion globale.'),('Toutes les instances à la fois','Chaque appel d’instance possède son objet courant.')],'$this->num désigne le numéro de cet objet.','facile')
Q(2,8,'Instance','Quelle notation appelle une méthode d’instance ?', [('$personne->getNum()','-> accède à un membre de l’objet.'),('Personne::getNum() sans objet','Le getter présenté utilise $this ; ce n’est pas une méthode statique.'),('$personne.getNum()','Le point est un opérateur de concaténation.'),('$personne["getNum"]','Cette syntaxe est un accès de type tableau.')],'Pour l’objet : ->. Pour une méthode statique : ::.','facile')
Q(2,9,'Constructeur','Quand __construct est-il appelé ?', [('Lors d’une instanciation avec new','PHP appelle automatiquement le constructeur défini.'),('Après chaque echo','echo ne crée pas d’objet.'),('Seulement à la destruction','C’est __destruct qui est concerné.'),('Uniquement lors d’un appel statique','L’instanciation avec new n’est pas un appel statique.')],'Le constructeur initialise la nouvelle instance.','facile')
Q(2,[10,21],'Constructeur','Quel est le nom exact du constructeur moderne en PHP ?', [('__construct','Deux underscores précèdent construct.'),('construct','Cette méthode ordinaire ne devient pas le constructeur.'),('_construct','Il manque un underscore.'),('__constructor','Ce nom n’est pas le constructeur magique PHP.')],'Certaines diapositives masquent les underscores ; la syntaxe exécutable est __construct.','facile')
Q(2,11,'Constructeur','Quelle ligne initialise correctement la propriété nom ?', [('$this->nom = $leNom;','La propriété de l’objet reçoit le paramètre.'),('$nom = $leNom;','Cela crée ou modifie une variable locale.'),('$this->$leNom = nom;','Cela n’affecte pas la propriété nom visée.'),('self::nom = $leNom;','Cette syntaxe ne désigne pas la propriété d’instance.')],'Un paramètre et une propriété ne se confondent pas.')
Q(2,12,'Constructeur','Peut-on définir plusieurs méthodes __construct de signatures différentes dans une même classe PHP ?', [('Non','On ne redéfinit pas plusieurs fois une méthode de même nom dans la classe.'),('Oui, comme plusieurs surcharges distinctes','Le cours présente une simulation dans un seul constructeur.')],'Le cours choisit le comportement avec func_num_args et func_get_arg.','facile',kind='vrai-faux')
Q(2,12,'Arguments','Que renvoie func_num_args() dans une fonction ?', [('Le nombre d’arguments effectivement reçus','Il permet de choisir un cas dans le constructeur du cours.'),('Le premier argument','Il faut func_get_arg(0).'),('Le nombre de propriétés de la classe','Les propriétés ne sont pas les arguments.'),('Le nombre d’instances créées','Aucun comptage global d’objets n’est effectué.')],'Cette fonction compte les arguments de l’appel courant.','facile')
Q(2,13,'Arguments','Pour new Personne(12, "Dupont", "TechNova"), que renvoie func_get_arg(1) dans le constructeur ?', [('Dupont','Le premier argument est à l’indice 0, le deuxième à 1.'),('12','12 correspond à l’indice 0.'),('TechNova','TechNova correspond à l’indice 2.'),('3','3 est le nombre d’arguments.')],'Les positions commencent à zéro.','facile')
Q(2,14,'Arguments','Dans le constructeur du cours, quel cas traite deux arguments ?', [('case 2','Le switch porte sur le nombre d’arguments.'),('case 1','L’indexation de func_get_arg commence à zéro, mais le nombre reste 2.'),('case 3','Ce cas traite les trois informations.'),('default uniquement','Le cas 2 est explicitement prévu.')],'Ne pas confondre un nombre d’arguments avec un indice.')
Q(2,[14,15],'Arguments','Quelle société reçoit new Personne(13, "Martin") dans l’exemple de surcharge ?', [('inconnu','Le cas 2 affecte cette valeur par défaut.'),('TechNova','Cette société appartient à l’autre exemple.'),('Martin','Martin est le nom.'),('null obligatoirement','Le code définit explicitement une chaîne.')],'Le comportement dépend du nombre d’arguments reçu.')
Q(2,14,'Contrôle','À quoi sert break après un case dans le switch du constructeur ?', [('Sortir du switch','Cela empêche de poursuivre dans les cas suivants.'),('Détruire tous les objets','break ne déclenche pas une destruction générale.'),('Retourner le nombre d’arguments','Ce nombre est calculé par func_num_args.'),('Sortir automatiquement de tout le script','exit arrête le script ; break sort ici du switch.')],'Sans break, l’exécution peut se poursuivre dans les branches suivantes.')
Q(2,14,'Contrôle','Que signifie default: exit(1); dans l’exemple ?', [('Arrêter le programme pour un nombre d’arguments non prévu','Le défaut n’accepte pas d’autres formats.'),('Créer un objet avec un argument par défaut','exit ne fournit pas de valeur de constructeur.'),('Passer automatiquement au cas 1','Aucun case 1 n’est présent.'),('Afficher le chiffre 1','Le paramètre entier est un statut de sortie.')],'L’exemple rejette les formats différents de deux ou trois arguments.')
Q(2,16,'Encapsulation','Pourquoi rendre les attributs de Voiture privés et exposer des méthodes ?', [('Contrôler leur lecture et modification','Les getters et setters organisent l’accès aux données.'),('Empêcher toute création de voiture','private sur les attributs n’interdit pas new.'),('Rendre chaque attribut statique','La visibilité ne change pas la portée.'),('Afficher automatiquement le HTML','Les attributs privés ne créent aucun affichage.')],'L’encapsulation protège la représentation interne.')
Q(2,18,'Méthodes','Que doit renvoyer calculerPrixLocation($nbJours) ?', [('$this->prixJournalier * $nbJours','Le coût est le prix par jour multiplié par la durée.'),('$this->prixJournalier + $nbJours','Une addition ne calcule pas le coût total.'),('$nbJours seulement','Le tarif serait ignoré.'),('Le nombre de voitures','Cette méthode ne compte pas les instances.')],'La méthode utilise une donnée de l’instance et un paramètre.','facile')
Q(2,18,'Constructeur','Pour une Voiture créée avec quatre informations, quelle disponibilité est prévue ?', [('true','Le format à quatre arguments fixe disponible à true.'),('false','Ce n’est pas le défaut demandé.'),('Le prix journalier','Un montant n’est pas la disponibilité prévue.'),('Aucune propriété disponible','La propriété reste une partie de la classe.')],'L’énoncé précise le défaut à appliquer.','facile')
Q(2,[20,21],'Héritage','Quel mot-clé déclare une classe fille ?', [('extends','class Etudiant extends Personne établit l’héritage.'),('parent','parent désigne la mère dans un accès de portée.'),('static','static définit un membre à portée de classe.'),('new','new instancie une classe.')],'extends relie la classe fille à la classe mère.','facile')
Q(2,21,'Héritage','Quelle instruction appelle le constructeur de la mère ?', [('parent::__construct($nom);','La portée parent cible le constructeur de la mère.'),('$this->__construct($nom);','Cela rappellerait le constructeur courant.'),('parent->construct($nom);','parent se combine avec :: et le nom magique exact.'),('new parent($nom);','Créer un autre objet n’initialise pas la partie mère de l’objet courant.')],'L’exemple appelle explicitement le constructeur parent.','facile')
Q(2,21,'Héritage','Dans l’exemple Etudiant, quel attribut est propre à la classe fille ?', [('formation','Etudiant ajoute cet attribut privé.'),('nom','nom est défini protected dans Personne.'),('Personne','C’est le nom de la mère, pas un attribut.'),('parent','C’est un mot-clé de portée.')],'La fille ajoute sa donnée en plus de la partie Personne.','facile')
Q(2,[20,21],'Héritage','Une fille définit son propre constructeur. L’initialisation de la mère s’exécute-t-elle automatiquement en plus ?', [('Non, l’exemple l’appelle explicitement','parent::__construct transmet les paramètres nécessaires.'),('Oui, avec tous les arguments automatiquement','Le constructeur redéfini ne provoque pas cet appel implicite supplémentaire.')],'Le cours demande de placer l’appel parent au début ; ce placement est sa convention pédagogique, pas une obligation syntaxique PHP.','difficile',kind='vrai-faux')
Q(2,23,'Héritage','Une propriété num est private dans Personne. Comment Utilisateur peut-il obtenir sa valeur ?', [('Par une méthode publique héritée getNum()','Le getter de Personne peut accéder à son propre attribut privé.'),('Par $this->num directement dans la fille','L’attribut privé de la mère n’est pas directement accessible.'),('En remplaçant -> par .','Le point ne change pas la visibilité.'),('Avec $_GET["num"] automatiquement','Un paramètre HTTP n’est pas la propriété de l’objet.')],'La visibilité des méthodes permet un accès contrôlé aux données privées.')
Q(2,[24,25],'Destructeur','Quel est le nom de la méthode spéciale appelée à la destruction ?', [('__destruct','C’est le nom magique du destructeur.'),('__destroy','Ce n’est pas le nom PHP prévu.'),('destruct seulement','Sans les deux underscores, il s’agit d’une méthode ordinaire.'),('__construct','C’est le constructeur.')],'Le nom exact comporte deux underscores.','facile')
Q(2,[25,26],'Destructeur','Dans l’exemple avec une seule Voiture, quel ordre de messages est attendu ?', [('Création, Fin du programme, Destruction','L’objet est créé puis le script atteint echo avant la destruction de fin.'),('Destruction, Création, Fin du programme','La destruction n’a pas lieu avant la création.'),('Création, Destruction, Fin du programme','La référence existe encore au moment de l’echo final.'),('Fin du programme seulement','Constructeur et destructeur contiennent aussi des echo.')],'La capture du support confirme cet ordre.')
Q(2,24,'Références','Deux variables référencent le même objet. Si une seule reçoit null, est-il nécessairement détruit immédiatement ?', [('Non','L’autre référence maintient l’objet en vie.'),('Oui','Affecter null à une référence ne supprime pas les autres références.')],'La destruction dépend de l’absence de références, pas du seul nom d’une variable.','difficile',kind='vrai-faux')
Q(2,27,'Statique','À qui appartient une propriété static ?', [('À la classe','Elle est commune aux instances de cette classe.'),('À chaque instance séparément','C’est le fonctionnement d’une propriété d’instance.'),('Seulement au dernier objet créé','Elle n’est pas attachée au dernier objet.'),('Au navigateur','La portée est une règle du langage PHP.')],'Une donnée statique a une portée de classe.','facile')
Q(2,[27,28],'Statique','Comment appeler la méthode statique publique donnePlanete de Personne ?', [('Personne::donnePlanete()',':: appelle la méthode de classe.'),('Personne->donnePlanete()','-> nécessite une expression d’objet.'),('Personne.donnePlanete()','Le point est une concaténation.'),('new donnePlanete()','Ce n’est pas un nom de classe à instancier.')],'Le cours distingue NomClasse::methode et $objet->methode.','facile')
Q(2,27,'Statique','Quelle expression lit la propriété statique privée $planete depuis sa classe ?', [('self::$planete','Le dollar est requis pour une propriété statique.'),('self::planete','Sans $, on désigne une constante de classe.'),('$this->planete','Ce serait un accès à une propriété d’instance.'),('self->planete','self utilise la résolution de portée ::.')],'La diapositive contient une coquille : self::$planete est la syntaxe correcte.')
Q(2,27,'Statique','Quelles écritures correspondent à une méthode statique renvoyant la planète ?', [('public static function donnePlanete() { return self::$planete; }','Déclaration statique et accès à la propriété statique cohérents.'),('public function donnePlanete() { return $this->planete; }','C’est une méthode d’instance et un accès d’instance.'),('public static function donnePlanete() { return $this->planete; }','$this n’est pas disponible dans une méthode statique.'),('public static donnePlanete() { return self::$planete; }','Le mot-clé function manque.')],'Une méthode statique ne possède pas d’objet courant.')
Q(2,31,'Compteur','Où incrémenter le compteur statique pour compter chaque nouvel utilisateur créé ?', [('Dans le constructeur Utilisateur','L’initialisation commune peut compter chaque construction.'),('Seulement dans afficherInfos','Plusieurs affichages compteraient plusieurs fois.'),('Seulement dans getNombreUtilisateurs','Lire le compteur ne doit pas modifier le total.'),('Dans le destructeur pour compter les créations','Le destructeur se produit à la fin de vie, pas à la création.')],'Le cours demande une incrémentation à chaque création.')
Q(2,[31,32],'Compteur','Deux formateurs et trois apprenants sont créés, et chacun appelle une fois le constructeur Utilisateur. Quel compteur commun est attendu ?', [('5','2 + 3 créations passent dans le constructeur commun.'),('2','Les apprenants doivent aussi être comptés.'),('3','Les formateurs doivent aussi être comptés.'),('6','Aucune sixième création n’est décrite.')],'La capture affiche un total de cinq utilisateurs.','facile')
Q(2,7,'Instance','Qu’affiche ce programme si getNum et setNum sont ceux du cours ?', [('12','Le numéro de $a reste indépendant de celui de $b.'),('13','$b est une autre instance.'),('1213','Un seul appel echo est présent.'),('0','setNum a bien affecté la valeur.')],'Les propriétés d’instance appartiennent à chaque objet.',code='$a = new Personne(); $b = new Personne();\n$a->setNum(12); $b->setNum(13);\necho $a->getNum();')
Q(2,7,'Instance','Quel est le problème de ce setter ?', [('Il modifie une variable locale et non l’attribut','Il faut écrire $this->num = $nvNum.'),('Le nom setNum est interdit','Le nom de méthode est valide.'),('Un setter doit toujours être statique','Il modifie ici une instance.'),('Un paramètre ne peut pas être utilisé dans une méthode','Les paramètres sont autorisés.')],'La propriété nécessite $this->.',code='public function setNum($nvNum) { $num = $nvNum; }')
Q(2,5,'Visibilité','Un script fait echo $p->num alors que num est private. Que se passe-t-il ?', [('L’accès est interdit','Il faut passer par une méthode autorisée, comme getNum.'),('Le nom de la propriété est affiché','L’accès ne se transforme pas en chaîne.'),('PHP convertit automatiquement private en public','Les règles de visibilité sont appliquées.'),('Le constructeur est rappelé','Lire une propriété n’appelle pas __construct.')],'private interdit l’accès direct depuis l’extérieur.')
Q(2,6,'Méthodes','Dans la terminologie du cours, une méthode de type procédure…', [('Réalise une action sans renvoyer de résultat explicite','Le cours oppose l’action à la fonction qui renvoie une valeur.'),('Doit s’appeler procedure','Le mot-clé de déclaration reste function.'),('Se déclare sans function','Toutes les méthodes montrées utilisent function.'),('Ne peut pas utiliser les attributs','Une méthode d’instance peut utiliser $this.')],'« Procédure » décrit ici le rôle, pas un mot-clé PHP.','facile')
Q(2,11,'Constructeur','Que manque-t-il dans ce code pour initialiser correctement le nom ?', [('$this-> devant nom','Il faut affecter la propriété, pas la variable locale.'),('static devant function','Le constructeur doit initialiser une instance.'),('Un echo avant $nom','Afficher ne stocke pas dans l’objet.'),('Un second constructeur','Le même nom de méthode ne peut pas être déclaré deux fois.')],'Le paramètre et la propriété sont deux emplacements différents.',code='class Personne {\n private $nom;\n public function __construct($nom) { $nom = $nom; }\n}')
Q(2,22,'Héritage','À quoi sert parent:: dans une classe fille ?', [('Désigner un membre de la classe mère accessible dans ce contexte','Par exemple parent::__construct(...).'),('Créer automatiquement tous les objets parents','Il s’agit d’un accès de portée.'),('Rendre les propriétés privées publiques','Les visibilités ne sont pas modifiées.'),('Parcourir un tableau','C’est le rôle de foreach.')],'parent désigne la classe parente.')
Q(2,30,'Héritage','Comment éviter de réécrire l’affichage commun dans Formateur::afficherInfos() ?', [('Appeler parent::afficherInfos(), puis afficher la spécialité','On réutilise la méthode accessible de la mère.'),('Appeler $this->afficherInfos() au début de la même méthode','Cela rappelle la même méthode et peut boucler récursivement.'),('Supprimer la méthode de la mère','La duplication ne sera pas résolue pour les autres filles.'),('Utiliser func_num_args pour afficher le nom','Cela compte les arguments, sans réutiliser l’affichage commun.')],'L’héritage permet la réutilisation des comportements communs.')
Q(2,31,'Compteur','Quel corps convient à getNombreUtilisateurs() dans Utilisateur ?', [('return self::$nombreUtilisateurs;','La méthode renvoie la donnée à portée de classe.'),('return $this->nombreUtilisateurs;','Le getter statique ne possède pas $this.'),('self::$nombreUtilisateurs++;','Cela modifie le compteur au lieu de seulement le renvoyer.'),('return $nombreUtilisateurs;','Cette variable locale n’est pas la propriété statique.')],'Le getter ne doit pas incrémenter le compteur.')
Q(2,8,'Encapsulation','Quelles opérations respectent une propriété num privée et ses accesseurs publics ?', [('$p->setNum(123);','L’accès passe par le setter.'),('echo $p->getNum();','L’accès passe par le getter.'),('$p->num = 123;','L’écriture directe depuis l’extérieur est interdite.'),('echo $p->num;','La lecture directe depuis l’extérieur est interdite.')],'Les méthodes publiques forment l’interface d’accès.','intermediaire',[0,1],'multiple')
Q(2,13,'Arguments','Quel accès fournit la société lors d’un appel à trois arguments dans l’ordre numéro, nom, société ?', [('func_get_arg(2)','La société est la troisième valeur, donc à l’indice 2.'),('func_get_arg(3)','L’indice 3 serait la quatrième valeur.'),('func_num_args(2)','Cette fonction compte les arguments ; elle n’en extrait pas un.'),('func_get_arg(0)','L’indice 0 fournit le numéro.')],'L’indexation est zéro, un, deux.')
Q(2,18,'Méthodes','Un tarif journalier vaut 45 et la durée vaut 3. Que doit renvoyer calculerPrixLocation ?', [('135','45 × 3 = 135.'),('48','C’est la somme, pas le produit.'),('15','C’est la division, pas le coût de trois jours.'),('45','La durée a été ignorée.')],'Une méthode de calcul renvoie le produit tarif × durée.','facile')
Q(2,27,'Statique','Quel ensemble est cohérent pour déclarer une planète commune puis la renvoyer ?', [('private static $planete = "Terre"; et return self::$planete;','La déclaration et l’accès ont la même portée de classe.'),('private $planete = "Terre"; et return self::$planete;','La déclaration est d’instance mais l’accès est statique.'),('private static $planete = "Terre"; et return $planete;','La variable locale n’est pas la propriété statique.'),('private static $planete = "Terre"; et return self::planete;','Il manque le dollar pour lire la propriété.')],'Le mot static et la syntaxe self::$… doivent correspondre.','difficile')
Q(2,30,'Héritage','Formateur et Apprenant héritent d’Utilisateur. Quelles données faut-il regrouper dans la mère selon l’exercice ?', [('id, nom et email','Ces informations sont communes aux deux catégories.'),('specialite uniquement','specialite appartient au Formateur.'),('formation uniquement','formation appartient à l’Apprenant.'),('Toutes les vues HTML du site','L’exercice porte sur une classe métier Utilisateur.')],'La mère concentre les attributs communs.','facile')
Q(2,27,'Portée','Vrai ou faux : changer une propriété d’instance de $a modifie automatiquement celle de $b, un autre objet créé avec new.', [('Faux','Deux instances distinctes possèdent leurs propres valeurs d’instance.'),('Vrai','La propriété commune aux instances serait une propriété statique.')],'Ne pas confondre propriété d’instance et propriété de classe.','facile',kind='vrai-faux')
# CHAPITRE 3 — DAO, persistance et connexion
Q(3,3,'Persistance','Pourquoi les seuls objets en mémoire ne suffisent-ils pas à une application de gestion ?', [('Leurs données disparaissent à la fin de l’exécution','Un stockage durable est nécessaire.'),('Ils ne peuvent contenir aucune donnée','Les propriétés stockent bien des données pendant l’exécution.'),('Ils exécutent forcément du HTML','Un objet métier n’est pas une vue.'),('Ils interdisent les méthodes','Les méthodes sont un élément de la POO.')],'La persistance conserve les informations au-delà de la vie du programme.','facile')
Q(3,4,'Persistance','Quelles sont les deux étapes de mise en place de la persistance décrites ?', [('Prévoir une structure permanente','La base ou le fichier accueille durablement les informations.'),('Créer une passerelle avec les objets','Il faut enregistrer et retrouver les données du modèle objet.'),('Supprimer toutes les classes métier','Elles restent nécessaires au modèle objet.'),('Afficher tous les objets avec echo','Un affichage n’est pas un stockage.')],'Structure de stockage et passerelle sont complémentaires.','facile',[0,1],'multiple')
Q(3,4,'Stockage','Quels supports permanents le cours cite-t-il ?', [('Base relationnelle et fichier XML','Les deux supports sont explicitement mentionnés.'),('Uniquement les variables locales','Elles ne sont pas permanentes.'),('Uniquement les propriétés private','La visibilité ne conserve pas les données après exécution.'),('Uniquement les sous-vues HTML','Une vue affiche les informations.')],'La persistance n’impose pas uniquement une base relationnelle.','facile')
Q(3,5,'Passerelle','Créer une table Personne suffit-il pour que l’objet Personne se sauvegarde tout seul ?', [('Non','Le code de liaison objet/stockage reste à écrire.'),('Oui','Une classe et une table ne sont pas automatiquement reliées.')],'Le DAO assure cette passerelle.','facile',kind='vrai-faux')
Q(3,6,'Couplage','Quel problème apparaît si Personne contient directement son SQL ?', [('Un couplage étroit entre métier et stockage','Changer le stockage oblige à toucher le code métier.'),('Une disparition de toutes les propriétés','Les propriétés ne disparaissent pas.'),('L’impossibilité de créer des objets','La présence de SQL n’interdit pas new.'),('Une séparation complète des responsabilités','Le SQL est justement mélangé au métier.')],'Le cours motive les DAO par la réduction de ce couplage.','facile')
Q(3,7,'DAO','Quelle solution isole l’accès au stockage ?', [('Une classe DAO associée au métier','Elle concentre les échanges avec la structure permanente.'),('Des requêtes copiées dans toutes les vues','Cela disperse l’accès aux données.'),('Des attributs publics supplémentaires','La visibilité ne remplace pas une couche de persistance.'),('Un echo dans chaque constructeur','Un affichage ne réalise pas la sauvegarde.')],'Le DAO est un objet d’accès aux données.','facile')
Q(3,8,'Responsabilités','Quelle méthode appartient naturellement à PersonneDAO ?', [('insertionPersonne($personne)','Elle enregistre les informations dans le stockage.'),('afficherMenuHTML()','C’est une responsabilité de présentation.'),('dessinerBouton()','C’est une opération d’interface.'),('choisirCouleurDuSite()','Cela concerne la présentation du site.')],'Le DAO gère notamment insertion et suppression.','facile')
Q(3,9,'Architecture','N couches signifie-t-il obligatoirement N machines physiques ?', [('Non','Plusieurs couches peuvent fonctionner sur une seule machine.'),('Oui','Le cours distingue explicitement couches et machines.')],'La séparation logique ne dicte pas un déploiement physique.','facile',kind='vrai-faux')
Q(3,10,'Architecture','Quel chemin correspond au schéma de couches du cours ?', [('Utilisateur, interface, métier, DAO, base','Le DAO est entre le métier et le stockage.'),('Utilisateur, base, interface, DAO, métier','La base n’est pas l’interface utilisateur.'),('DAO, utilisateur, base, métier, interface','Cela ne suit pas le rôle des couches.'),('Interface, base, utilisateur, DAO','La base ne relaie pas les actions de l’utilisateur vers l’interface.')],'Le schéma attribue une responsabilité à chaque couche.')
Q(3,11,'DAO','Un même objet DAO peut-il servir plusieurs objets d’une même classe métier ?', [('Oui','Le cours prévoit le même DAO pour ces objets.'),('Non, un DAO par instance est obligatoire','Ce n’est pas le principe énoncé.')],'Un DAO ne représente pas une seule occurrence métier.','facile',kind='vrai-faux')
Q(3,11,'DAO','Quelle association de classes le cours propose-t-il ?', [('Personne et PersonneDAO','Une classe métier possède sa classe DAO associée.'),('Personne et MenuCSS','Cela ne décrit pas l’accès au stockage.'),('PersonneDAO et aucun objet métier possible','Un DAO échange notamment des objets métier.'),('Toutes les classes dans une unique vue','Cela contredit la séparation présentée.')],'La responsabilité de persistance est associée à l’entité métier.','facile')
Q(3,12,'Évolution','On passe de la base à un fichier en gardant la même interface DAO. Que faut-il principalement réécrire ?', [('L’intérieur des méthodes du DAO','Le métier conserve son interface vers la persistance.'),('Tous les getters métier','Ils ne dépendent pas du support de stockage.'),('Tous les écrans sans exception','La séparation vise à préserver les autres couches.'),('Tous les noms des objets métier','Le changement de support ne l’exige pas.')],'Le DAO limite l’impact d’un changement de stockage.')
Q(3,12,'Factorisation','Quel avantage apporte la centralisation du code d’accès aux données ?', [('Éviter sa répétition dans plusieurs endroits','Les opérations sont regroupées dans le DAO.'),('Supprimer toute base de données','La base reste un support possible.'),('Rendre le code SQL visible dans le navigateur','Ce n’est pas le but.'),('Remplacer les règles métier par du CSS','Les responsabilités restent distinctes.')],'Factoriser signifie regrouper le code commun.','facile')
Q(3,13,'Métier','Quel membre est cohérent dans la classe métier Soiree ?', [('getLaNature()','Il renvoie une propriété de la soirée.'),('Une connexion unique au serveur pour toute l’application','Le cours la place dans GestionConnexion.'),('Une sous-vue de menu','Elle appartient à la présentation.'),('Un routeur de contrôleurs HTTP','Ce n’est pas la responsabilité métier de Soiree.')],'La soirée décrit les données et comportements métier.','facile')
Q(3,14,'DAO','Dans creer($objLaSoiree), pourquoi appeler les getters de l’objet ?', [('Pour récupérer les valeurs à enregistrer','Le DAO lit les informations de l’objet métier.'),('Pour transformer l’objet en vue','Le rôle est la persistance.'),('Pour appeler le destructeur','Les getters n’ont pas ce rôle.'),('Pour rendre les attributs automatiquement publics','La visibilité reste inchangée.')],'La passerelle utilise les informations métier pour le stockage.')
Q(3,15,'XML','Que montre le remplacement de la base par du XML dans SoireeDAO ?', [('Le changement d’implémentation derrière une responsabilité stable','creer enregistre toujours la soirée, avec un autre support.'),('L’obligation de supprimer Soiree','Le modèle métier est préservé.'),('L’exécution du XML par le navigateur comme PHP','Ce n’est pas le fonctionnement présenté.'),('La fin de toute persistance','Le fichier fournit justement un support permanent.')],'Le DAO masque les détails du stockage.')
Q(3,16,'Conception','Pour une structure importante, quelle granularité le cours suggère-t-il ?', [('Une classe DAO par table','La classe regroupe les opérations sur cette table.'),('Une classe DAO par bouton','Le bouton appartient à l’interface.'),('Une classe DAO par caractère d’une chaîne','Aucun rapport avec la structure persistante.'),('Aucune classe DAO','Le cours en recommande pour organiser la persistance.')],'La taille du stockage influence l’organisation des DAO.')
Q(3,17,'PDO','Quelle API PHP d’accès aux bases relationnelles est citée ?', [('PDO','PHP Data Objects est l’API PHP du cours.'),('JDBC','JDBC est présenté pour Java.'),('OLE DB','Le cours l’associe à l’environnement .NET.'),('MVC','MVC organise l’application ; ce n’est pas cette API.')],'Ne pas confondre API d’accès aux données et architecture.','facile')
Q(3,17,'API','Que signifie API dans ce contexte ?', [('Application Programming Interface','Un ensemble d’outils utilisables par les programmes.'),('Une table relationnelle particulière','Une API n’est pas une table.'),('Un objet métier unique','Ce n’est pas la définition.'),('Le nom d’un fichier PHP obligatoire','Une API est une interface de programmation.')],'PDO, JDBC et les API citées accomplissent des responsabilités d’accès aux données.')
Q(3,18,'Connexion','Quel est le rôle de GestionConnexion ?', [('Fournir une connexion aux DAO','Le DAO utilise ensuite cette connexion.'),('Afficher les vues de chaque page','C’est la présentation.'),('Définir la nature de chaque soirée','C’est une donnée métier.'),('Remplacer toutes les opérations CRUD','La connexion seule n’est pas le CRUD.')],'La classe technique sépare gestion de connexion et opérations métier.','facile')
Q(3,18,'Singleton','Quel objectif motive le Singleton de connexion ?', [('Limiter la création de connexions en réutilisant celle fournie','Cela maîtrise la charge du serveur de données.'),('Créer une connexion par getter','C’est l’inverse de la réutilisation.'),('Interdire tous les objets DAO','Ils utilisent la connexion.'),('Garder tous les objets métier éternellement','Le Singleton de connexion n’assure pas cette persistance.')],'Le Singleton de l’exemple centralise la connexion.','facile')
Q(3,19,'Singleton','Pourquoi le constructeur de GestionConnexion est-il private ?', [('Pour contrôler la création depuis la classe','Le programme passe par getConnexion.'),('Pour empêcher la classe d’utiliser PDO','Le constructeur crée lui-même un PDO.'),('Pour rendre les propriétés publiques','Ce sont deux choix distincts.'),('Pour imposer new GestionConnexion() à l’extérieur','private interdit justement cet appel extérieur.')],'La création est contrôlée par la méthode statique.')
Q(3,19,'Singleton','Quel appel le programme doit-il utiliser pour obtenir la connexion ?', [('GestionConnexion::getConnexion()','La méthode publique est statique.'),('new GestionConnexion()','Le constructeur présenté est privé.'),('GestionConnexion->getConnexion()','-> nécessite un objet.'),('$_POST["connexion"]','Un champ HTTP ne fournit pas l’objet PDO.')],'Le point d’accès public est la méthode de classe.','facile')
Q(3,19,'Singleton','À quoi sert is_null(self::$_instance) dans getConnexion ?', [('Détecter l’absence d’instance','On ne crée l’instance que si elle manque.'),('Compter les soirées','Aucun comptage métier ici.'),('Vérifier le nom d’utilisateur HTTP','Ce n’est pas un paramètre HTTP.'),('Fermer systématiquement la connexion','Le test prépare une création éventuelle.')],'La condition permet l’initialisation à la première demande.')
Q(3,19,'PDO','Quelles informations apparaissent dans new PDO(...) dans le support ?', [('Un DSN MySQL avec hôte et base','Il indique le support et la base visés.'),('Un identifiant et un mot de passe','Ils sont passés en arguments.'),('Un chemin obligatoire vers layout.php','La connexion ne dépend pas de cette vue.'),('Le nombre de vues HTML','Ce n’est pas un paramètre de PDO.')],'Le cours montre new PDO(DSN, login, mdp).','intermediaire',[0,1],'multiple')
Q(3,19,'Singleton','Que renvoie getConnexion dans l’exemple ?', [('self::$laConnexion','Le résultat est l’objet de connexion PDO conservé.'),('Le HTML du menu','Aucun affichage de vue ici.'),('Le premier objet Soiree','La connexion n’est pas une soirée.'),('Toujours null','La méthode initialise avant de renvoyer si nécessaire.')],'$_instance pilote la création ; $laConnexion est la valeur renvoyée.')
Q(3,19,'Connexion','Que fait liberer() dans la classe technique du cours ?', [('Mettre les deux références statiques à null','Elle cesse de conserver instance et connexion dans ces propriétés.'),('Supprimer toutes les tables','Aucune requête DROP n’est présente.'),('Effacer le code métier','Les classes ne sont pas supprimées.'),('Afficher automatiquement les données','Ce n’est pas un affichage.')],'D’autres références éventuelles à PDO peuvent encore exister.','difficile')
Q(3,20,'DAO instance','Où l’approche avec un objet DAO conserve-t-elle sa connexion ?', [('Dans une propriété privée d’instance','Le constructeur l’initialise via GestionConnexion.'),('Dans le nom du fichier HTML','Un nom de fichier ne conserve pas cet objet.'),('Dans chaque attribut métier nom','Les données métier restent distinctes.'),('Dans une constante textuelle "PDO"','Une chaîne ne remplace pas une connexion.')],'Le DAO possède ici $this->laConnexion.')
Q(3,20,'DAO instance','Quel constructeur initialise correctement la connexion du DAO ?', [('public function __construct() { $this->laConnexion = GestionConnexion::getConnexion(); }','Il affecte la propriété d’instance.'),('public function __construct() { $laConnexion = GestionConnexion::getConnexion(); }','Cette variante conserve seulement une variable locale.'),('public function __construct() { echo "connexion"; }','Afficher une chaîne n’obtient pas PDO.'),('private $laConnexion = "PDO";','Une chaîne ne représente pas la connexion.')],'Il faut affecter l’attribut utilisé par les autres méthodes.')
Q(3,21,'DAO statique','Dans la seconde forme de DAO, comment les méthodes sont-elles déclarées ?', [('public static function ...','L’appel direct par la classe est alors possible.'),('Uniquement private sans function','Une méthode nécessite function.'),('Comme des champs de formulaire','Ce sont des méthodes PHP.'),('Avec extends à la place de function','extends déclare l’héritage.')],'Le cours oppose DAO d’instance et méthodes DAO statiques.','facile')
Q(3,[20,21],'DAO statique','Quel couple appel/déclaration est cohérent ?', [('NomTableDAO::inserer(...) avec public static function inserer(...)','La portée de l’appel correspond à la déclaration.'),('NomTableDAO->inserer(...) avec une classe non instanciée','Il manque un objet avant ->.'),('$dao["inserer"] avec une méthode d’instance','Ce n’est pas un appel de méthode.'),('inserer::NomTableDAO(...)','L’ordre classe puis méthode est inversé.')],'Pour la forme d’instance, on crée un objet puis on utilise ->.')
Q(3,22,'CRUD','Que désigne le C de CRUD ?', [('Create : créer une donnée','C’est l’ajout d’un enregistrement.'),('Connect : uniquement ouvrir PDO','La connexion n’est pas le C de CRUD.'),('Control : sélectionner une vue','Cela concerne plutôt le contrôleur.'),('Count : exclusivement compter','Un comptage relève d’une lecture calculée.')],'CRUD décrit quatre familles d’opérations persistantes.','facile')
Q(3,22,'CRUD','Quelles opérations appartiennent au CRUD ?', [('Read','C’est la lecture ou recherche.'),('Update','C’est la modification.'),('Render','C’est de l’affichage, pas le R du CRUD.'),('Route','Le routage ne constitue pas une opération CRUD.')],'CRUD signifie Create, Read, Update, Delete.','facile',[0,1],'multiple')
Q(3,23,'Create','Quelles signatures de création sont proposées ?', [('creer($date, $nature, $places)','On transmet les valeurs séparées.'),('creer($objetSoiree)','On transmet un objet métier.'),('creer() sans aucune information ni autre source','L’opération a besoin des informations à stocker.'),('creer($vueHTML) obligatoirement','Le cours n’impose pas une vue comme donnée.')],'Les données peuvent être transmises séparément ou via un objet.','intermediaire',[0,1],'multiple')
Q(3,24,'Create','Quels retours peuvent être utiles après une création ?', [('Un booléen de réussite','Il informe l’appelant du succès ou de l’échec.'),('L’identifiant généré','Il permet de retrouver l’enregistrement créé.'),('Obligatoirement une page CSS','Ce n’est pas un retour de création décrit.'),('Aucun retour n’est jamais autorisé','Le cours décrit justement des variantes de type fonction.')],'Le contrat de la méthode détermine son résultat.','intermediaire',[0,1],'multiple')
Q(3,25,'Read','Lesquels sont les trois types de résultats de lecture du cours ?', [('Un objet, une collection, une donnée calculée','Ces trois variantes sont décrites.'),('Un header, un footer, un menu','Ce sont des sous-vues.'),('Une insertion, une suppression, une modification','Ce sont les autres opérations CRUD.'),('Toujours un seul booléen','La lecture n’est pas limitée à un booléen.')],'Le retour dépend de ce qui est recherché.','facile')
Q(3,26,'Finders','Quel est le rôle de findById($id) ?', [('Rechercher l’enregistrement désigné par son identifiant','L’identifiant sélectionne une occurrence unique.'),('Renvoyer tous les tuples sans filtre','C’est findAll.'),('Supprimer l’enregistrement','C’est une opération Delete.'),('Créer un identifiant dans chaque vue','Ce n’est pas un finder.')],'Un finder est une méthode de recherche.','facile')
Q(3,26,'Finders','Quelle méthode lit toute la table selon les noms du cours ?', [('findAll()','Elle recherche tous les tuples.'),('findById($id)','Elle cible un identifiant.'),('creer($objet)','Elle ajoute une occurrence.'),('detruire($id)','Elle supprime une occurrence.')],'findAll et findById diffèrent par leur sélection.','facile')
Q(3,25,'Read','Une méthode renvoie le nombre de places réservées. À quelle famille appartient-elle ?', [('Read','C’est une donnée calculée lue.'),('Create','Aucune création n’est décrite.'),('Update','Aucune donnée n’est modifiée.'),('Delete','Aucune suppression n’est décrite.')],'Une lecture peut renvoyer un calcul, pas seulement des objets.')
Q(3,27,'Update','Quels paramètres peuvent être prévus pour une modification ?', [('Un identifiant et les nouvelles valeurs','L’identifiant cible la donnée et les valeurs décrivent le changement.'),('Un objet métier contenant les modifications','C’est la seconde variante citée.'),('Toujours aucun paramètre et aucune autre source','Le DAO doit savoir quoi modifier.'),('Une vue HTML obligatoire','Le contrat porte ici sur la donnée métier.')],'Le cours présente deux formes d’entrée pour Update.','intermediaire',[0,1],'multiple')
Q(3,27,'Update','Une méthode Update doit-elle obligatoirement renvoyer un booléen ?', [('Non','Le cours indique que ce retour est possible, sans être obligatoire.'),('Oui','Le contrat peut aussi être de type procédure.')],'Il faut lire le contrat de la méthode.','facile',kind='vrai-faux')
Q(3,28,'Delete','Comment désigner l’élément à supprimer selon le cours ?', [('Par son identifiant ou par l’objet métier','Ces deux variantes sont indiquées.'),('Par la couleur de son bouton','Cela ne définit pas l’occurrence persistante.'),('Uniquement par le nom de la classe','Cela ne suffit pas à cibler une occurrence précise.'),('Uniquement avec un echo','echo ne supprime aucun enregistrement.')],'Delete agit sur un enregistrement identifié.','facile')
Q(3,30,'Stratégie 1','Dans la stratégie 1, qui connaît le DAO ?', [('L’objet métier','Il possède une référence au DAO et gère sa sauvegarde via lui.'),('Seulement la vue','Ce n’est pas le schéma décrit.'),('Aucun objet ni programme','Quelqu’un doit utiliser le DAO.'),('Uniquement le serveur SQL','Le DAO est du code de l’application.')],'Le programme utilisateur des objets métier peut ignorer le DAO.')
Q(3,31,'Stratégie 1','Quel appel illustre la stratégie 1 au niveau du programme ?', [('$uneSoiree->sauvegardeToi();','L’objet métier délègue à son DAO.'),('$dao->creer($uneSoiree); directement','Cela illustre la stratégie 2 au niveau du programme.'),('echo $uneSoiree;','Ce n’est pas un appel de persistance.'),('new SoireeDAO() uniquement','Créer le DAO seul ne demande pas la sauvegarde.')],'L’objet métier connaît et utilise sa passerelle.')
Q(3,32,'Stratégie 2','Pourquoi le cours privilégie-t-il souvent la stratégie 2 ?', [('Une meilleure isolation de la persistance','L’objet métier ne possède pas de référence au DAO.'),('L’absence de tout accès aux données','Le programme appelle le DAO.'),('Une sauvegarde automatique par PHP','Il faut toujours appeler les opérations.'),('L’obligation de supprimer les objets métier','Ils restent utilisés.')],'Le programme orchestre la persistance et le métier reste indépendant.')
Q(3,33,'Stratégie 2','Quelle séquence représente la stratégie 2 ?', [('Créer une Soiree, créer un SoireeDAO, appeler creer($soiree)','Le programme appelle le DAO avec l’objet métier.'),('Placer le SQL dans chaque getter','Cela mélange métier et stockage.'),('Appeler sauvegardeToi sans DAO connu du programme','Cela correspond à la stratégie 1.'),('Inclure seulement layout.php','C’est une opération d’affichage.')],'Le programme connaît explicitement les deux objets.')
Q(3,34,'Centralisation','Après mise en place des DAO, comment le reste de l’application doit-il accéder à une table ?', [('Via les méthodes du DAO correspondant','Le DAO devient le point de passage prévu.'),('En recopiant INSERT à chaque écran','Cela contourne la centralisation.'),('En rendant le mot de passe public dans HTML','Cela ne réalise pas une architecture DAO.'),('Via les propriétés CSS de la table HTML','Une table HTML n’est pas la table relationnelle.')],'Le support demande de ne pas contourner les DAO.','facile')
Q(3,19,'Syntaxe','Quelle correction donne accès à la connexion statique ?', [('self::$laConnexion','Une propriété statique exige le dollar.'),('self::laConnexion','Cela désigne un nom de constante.'),('$this->laConnexion dans une méthode statique','Aucun $this n’est disponible ici.'),('self->laConnexion','L’opérateur de portée de classe est ::.')],'La syntaxe est identique aux propriétés statiques du chapitre 2.')
Q(3,[14,33],'Syntaxe','Quel défaut empêche les autres méthodes de retrouver la connexion dans ce DAO ?', [('Le constructeur affecte une variable locale','Il faut $this->_db = GestionConnexion::getConnexion();'),('Le nom SoireeDAO est interdit','Le nom de classe est valide.'),('L’attribut est private','Les méthodes de la même classe peuvent y accéder.'),('GestionConnexion ne peut avoir de méthode statique','Le cours utilise précisément une méthode statique.')],'La propriété et la variable locale sont distinctes.',code='class SoireeDAO {\n private $_db;\n public function __construct() {\n   $_db = GestionConnexion::getConnexion();\n }\n}')
Q(3,[19,21],'Connexion','Quelle instruction correspond à la méthode liberer définie dans GestionConnexion ?', [('GestionConnexion::liberer();','C’est la méthode statique de la classe technique.'),('$pdo->liberer();','PDO ne possède pas cette méthode personnalisée.'),('echo liberer;','Ce n’est pas un appel de méthode.'),('new liberer();','liberer n’est pas une classe.')],'Une diapositive appelle liberer sur la connexion ; la méthode montrée appartient à GestionConnexion.','difficile')
# CHAPITRE 4 — MVC
Q(4,6,'MVC','Que signifie MVC ?', [('Modèle Vue Contrôleur','Les trois parties organisent données, affichage et coordination.'),('Méthode Variable Classe','Ce sont des notions PHP mais pas le sigle MVC.'),('Modèle Vue Connexion','Le C signifie contrôleur.'),('Module Valeur Constructeur','Ce n’est pas la décomposition du cours.')],'MVC sépare les responsabilités de l’application.','facile')
Q(4,5,'Conception','Qu’est-ce qu’un patron de conception ?', [('Une solution générale réutilisable à un problème récurrent','Il capitalise l’expérience de conception.'),('Un fichier PHP unique obligatoire','Un patron décrit une organisation, pas un fichier imposé.'),('Une correction de syntaxe uniquement','Il concerne la structure de l’application.'),('Un nom de table SQL','Ce n’est pas une structure de stockage.')],'Le cours présente MVC comme une organisation issue de cette expérience.','facile')
Q(4,4,'Conception','Quels problèmes relèvent de la conception décrite ?', [('Organiser les fichiers','C’est une question d’architecture.'),('Séparer PHP et HTML selon leurs responsabilités','Le cours l’identifie comme un enjeu d’organisation.'),('Choisir uniquement la valeur d’un prix','C’est une donnée métier, pas ce problème structurel.'),('Corriger uniquement une lettre dans un nom','Ce n’est pas l’enjeu architectural visé.')],'La conception traite notamment de l’organisation du code.','intermediaire',[0,1],'multiple')
Q(4,7,'Modèle','Où se trouvent les requêtes SQL dans l’architecture du cours ?', [('Dans le modèle','Le modèle accède aux données.'),('Dans chaque vue','Les vues ne contiennent pas les requêtes SQL.'),('Dans le navigateur','Le traitement SQL ne se fait pas dans l’affichage navigateur.'),('Dans les labels des formulaires','Les labels présentent les champs.')],'Le SQL appartient à la partie modèle.','facile')
Q(4,7,'Modèle','Le modèle peut-il être construit avec des fonctions ou avec des classes ?', [('Oui','Le cours cite les deux formes.'),('Non, uniquement avec du HTML','Le modèle contient les traitements de données, pas seulement l’affichage.')],'MVC ne nécessite pas exclusivement une implémentation orientée objet.','facile',kind='vrai-faux')
Q(4,8,'Modèle','Quel rôle joue ce fragment ?', [('Lire les données pour le modèle','Il interroge la base puis récupère les lignes.'),('Afficher les étudiants dans une vue','Aucun HTML ni echo ne sont présents.'),('Choisir la couleur du menu','Ce fragment n’a pas de présentation.'),('Instancier une classe Etudiant pour chaque ligne','fetchAll ne signifie pas automatiquement cet objet métier.')],'Le support utilise query et fetchAll pour obtenir les étudiants.',code='$sql = "SELECT * FROM etudiants";\n$resultat = $pdo->query($sql);\n$etudiants = $resultat->fetchAll();')
Q(4,9,'Vue','Quelle responsabilité correspond à la vue ?', [('Présenter les données à l’utilisateur','Elle contient principalement le HTML.'),('Ouvrir toutes les connexions à chaque paragraphe','Ce n’est pas sa responsabilité.'),('Rédiger toutes les requêtes SQL','Le SQL appartient au modèle.'),('Choisir les règles de persistance','Le modèle et les DAO les prennent en charge.')],'La vue réalise l’affichage.','facile')
Q(4,10,'Vue','Pourquoi une boucle foreach peut-elle apparaître dans une vue ?', [('Pour afficher les données déjà fournies','Le PHP de présentation peut parcourir la liste.'),('Pour déplacer toutes les requêtes SQL vers la vue','Le cours l’interdit.'),('Pour transformer le navigateur en moteur PHP','Le PHP reste exécuté côté serveur.'),('Pour créer nécessairement les tables','Un parcours n’implique pas une création SQL.')],'Une vue peut contenir du PHP destiné à la présentation.')
Q(4,10,'Vue','Quel mot-clé termine le foreach écrit avec la syntaxe alternative « : » ?', [('endforeach;','Il ferme ce bloc dans une vue.'),('endclass;','Ce n’est pas la fermeture de foreach.'),('return;','Cela quitte une fonction ou un fichier selon le contexte.'),('elseif;','C’est une branche conditionnelle, pas une fermeture de boucle.')],'Le cours utilise foreach (…) : puis endforeach;.','facile')
Q(4,11,'Contrôleur','Quelle responsabilité revient au contrôleur ?', [('Coordonner les traitements et prendre les décisions','Il gère la logique applicative.'),('Contenir exclusivement la mise en page CSS','C’est de la présentation.'),('Devenir systématiquement la base relationnelle','Le contrôleur n’est pas un stockage.'),('Remplacer tout modèle par du HTML','Il sollicite le modèle.')],'Le contrôleur organise l’exécution de l’application.','facile')
Q(4,12,'Cycle MVC','Quelle séquence correspond à une demande de liste ?', [('Demande, appel du modèle, résultat, appel de la vue','C’est la coordination montrée.'),('Vue, SQL dans le menu, suppression du modèle','Cela mélange les responsabilités.'),('Base, clic utilisateur, CSS, constructeur','Cet ordre ne décrit pas le cycle.'),('Afficher avant d’obtenir les données nécessaires','La liste doit être disponible à l’affichage.')],'Le contrôleur transmet à la vue les données obtenues.')
Q(4,12,'Contrôleur','Pourquoi inclure la vue après obtenirLesEtudiants($pdo) ?', [('La variable $etudiants est préparée avant son affichage','La vue peut parcourir les données.'),('La vue est un mot de passe de connexion','Ce n’est pas une information d’authentification.'),('include exécute le SQL à la place du modèle automatiquement','include charge le fichier demandé.'),('La fonction doit forcément afficher tout le HTML','La fonction du modèle fournit les données.')],'La préparation des données précède l’appel de la vue.')
Q(4,14,'Cycle MVC','Que reçoit finalement l’utilisateur dans le schéma ?', [('Du code HTML généré','Le navigateur affiche la réponse.'),('Les identifiants de connexion à la base','Ils ne constituent pas la réponse normale.'),('Le fichier PHP source complet','Le PHP est traité sur le serveur.'),('Uniquement la requête SQL','Le résultat est présenté via la vue.')],'Le cycle se conclut par une réponse destinée au navigateur.','facile')
Q(4,15,'Sous-vues','Qu’est-ce qu’une vue externe dans le cours ?', [('La page complète vue par l’internaute','Elle peut être composée de plusieurs sous-vues.'),('Un fichier SQL extérieur','Ce n’est pas une vue au sens présenté.'),('Le seul contrôleur principal','Le contrôleur reçoit et oriente les demandes.'),('Une classe DAO','Un DAO accède au stockage.')],'Il faut distinguer la page affichée et ses fragments.','facile')
Q(4,16,'Sous-vues','Quelles parties sont naturellement communes à plusieurs pages ?', [('Header et menu','Elles se répètent d’une page à l’autre.'),('Footer','Le pied de page est aussi une partie commune.'),('Les détails du film sélectionné','Ce contenu change selon la demande.'),('Les données propres à un étudiant précis','Ce contenu est spécifique.')],'Les sous-vues communes évitent la duplication.','facile',[0,1],'multiple')
Q(4,17,'Layout','Quel est le rôle de layout.php ?', [('Assembler la structure générale de la page','Il positionne les sous-vues et la zone centrale.'),('Stocker les mots de passe de PDO','Ce n’est pas une vue de structure.'),('Remplacer toutes les classes métier','Les responsabilités sont distinctes.'),('Supprimer les contrôleurs','Les demandes restent coordonnées par eux.')],'Le layout compose une page cohérente.','facile')
Q(4,18,'Sous-vues','Quelle différence sépare sous-vue commune et sous-vue liée à la demande ?', [('La seconde présente le contenu spécifique à l’action','La commune réutilise les parties partagées.'),('Une commune doit contenir du SQL','Les deux sont des éléments d’affichage.'),('Une sous-vue demandée ne peut pas contenir de HTML','Le cours la décrit comme un fichier PHP contenant du HTML.'),('La commune est obligatoirement une classe statique','Ce n’est pas sa définition.')],'La séparation limite la répétition et isole le contenu variable.')
Q(4,18,'Organisation','Où le cours regroupe-t-il les vues ?', [('Dans le répertoire vues à la racine','Les exemples utilisent aussi le nom views dans une arborescence.'),('Dans la table SQL controleurs','Les vues sont des fichiers dans le projet.'),('Uniquement dans $_REQUEST','$_REQUEST contient des paramètres, pas les vues.'),('Dans chaque propriété private','Une propriété ne constitue pas un répertoire.')],'Le nom du dossier doit être cohérent avec les chemins du projet.','facile')
Q(4,20,'Navigation','Après mise en place du contrôleur principal, comment organiser les liens du menu ?', [('Viser index.php avec les paramètres de navigation','Le point d’entrée oriente vers l’action.'),('Viser directement les fichiers du modèle','Le modèle ne doit pas être la page naviguée.'),('Afficher le SQL dans href','Le SQL n’est pas une URL de navigation.'),('Supprimer tous les liens','Le but est de rendre la navigation fonctionnelle.')],'Le cours centralise ensuite les demandes via le contrôleur principal.')
Q(4,22,'Point d’entrée','Quel fichier joue généralement le rôle de contrôleur principal ?', [('index.php','Le cours en fait le point d’entrée.'),('footer.php','C’est une sous-vue commune.'),('style.css','C’est un fichier de présentation.'),('film.sql','C’est un nom de script de données possible, pas le point d’entrée PHP.')],'Le point d’entrée reçoit les requêtes.','facile')
Q(4,22,'Point d’entrée','Quelles tâches sont attribuées au contrôleur principal dans ce cours ?', [('Traiter les paramètres de requête','Il oriente selon GET, POST ou REQUEST.'),('Orienter vers le sous-contrôleur adapté','Il centralise la navigation.'),('Mettre toutes les requêtes SQL dans les sous-vues','Le modèle contient le SQL.'),('Remplacer tous les formulaires par des connexions PDO','Ce n’est pas son rôle.')],'Le cours lui attribue aussi le chargement de la connexion et du layout.','intermediaire',[0,1],'multiple')
Q(4,23,'Routage','Que désigne le paramètre controleur dans l’URL du cours ?', [('Le sous-contrôleur à appeler','Le point d’entrée interprète ce choix.'),('La valeur à afficher dans tous les champs','Ce n’est pas la signification de ce paramètre.'),('Le mot de passe SQL','Le paramètre n’est pas un secret de connexion.'),('Le nom d’une propriété PHP imposée','C’est une convention de navigation du projet.')],'index.php reste le fichier demandé.','facile')
Q(4,24,'Sous-contrôleurs','Que peut faire un sous-contrôleur ?', [('Recevoir les paramètres nécessaires','Ils décrivent l’action demandée.'),('Appeler le modèle et transmettre ses données à la vue','Il coordonne le cas d’utilisation.'),('Devenir uniquement une feuille CSS','Il contient exclusivement du PHP selon le support.'),('Exiger que toute vue contienne du SQL','Le SQL reste dans le modèle.')],'Le sous-contrôleur gère un ensemble cohérent de fonctionnalités.','intermediaire',[0,1],'multiple')
Q(4,25,'Sous-contrôleurs','Quel regroupement correspond aux exemples du cours ?', [('etudiant.php pour les opérations sur les étudiants','Le sous-contrôleur porte un cas d’utilisation cohérent.'),('footer.php pour toutes les connexions','Le footer affiche le pied de page.'),('menu.php pour toutes les insertions SQL','Le menu est une sous-vue.'),('style.css pour la gestion des formations','Ce n’est pas un fichier de traitement PHP.')],'Les sous-contrôleurs sont regroupés dans controleurs.','facile')
Q(4,26,'Paramètres','Quelle expression récupère controleur via la superglobale employée sur la diapositive 26 ?', [('$_REQUEST["controleur"]','C’est l’expression explicitement présentée.'),('$_REQUEST->controleur','La superglobale est utilisée comme un tableau.'),('REQUEST("controleur")','Ce n’est pas une fonction de lecture.'),('$this->controleur automatiquement','Ce serait une propriété d’objet, pas la donnée reçue.')],'Les exemples ultérieurs utilisent aussi $_GET.')
Q(4,28,'Actions','Dans controleur=gererProduits&action=voirCategories, que désigne action ?', [('La fonctionnalité à exécuter','Le sous-contrôleur choisit ce traitement.'),('La classe mère de gererProduits','Il s’agit d’un paramètre de requête.'),('Le nombre de catégories','Il n’y a aucune quantité dans ce nom d’action.'),('Le nom de la base obligatoirement','La base est une autre configuration.')],'Le contrôleur et son action sont deux niveaux de sélection.','facile')
Q(4,29,'Actions','Quel traitement correspond à voirCategories ?', [('Lire les catégories puis inclure v_categories.php','C’est le cas montré dans le switch.'),('Supprimer le produit puis afficher footer.php','Aucune suppression n’est décrite.'),('Créer automatiquement une table','Il s’agit d’une consultation.'),('Lire seulement l’id produit pour modifierProduit','C’est une autre branche du switch.')],'Chaque case prépare les données utiles à sa vue.')
Q(4,29,'Actions','Quelles données sont préparées avant v_modif_produit.php ?', [('Le produit demandé','Son identifiant est récupéré dans les paramètres.'),('La liste des catégories','Elle est aussi lue avant la vue.'),('Une liste de mots de passe','Aucun traitement de ce type.'),('Uniquement le texte du footer','La vue de modification nécessite les données produit.')],'Le formulaire de modification a besoin du produit et des catégories.','intermediaire',[0,1],'multiple')
Q(4,29,'Switch','Pourquoi placer break après une action dans le switch ?', [('Pour éviter de poursuivre dans les actions suivantes','Une branche terminée quitte le switch.'),('Pour fermer la connexion systématiquement','break ne libère pas PDO.'),('Pour envoyer le formulaire HTML','Le bouton submit assure l’envoi.'),('Pour déclarer une nouvelle fonction','Ce n’est pas un mot-clé de déclaration.')],'Le principe du switch du chapitre 2 se retrouve dans les actions.')
Q(4,30,'Cycle MVC','Dans le schéma étudiants, qui appelle le modèle avant la vue ?', [('Le sous-contrôleur','Il obtient les données avant de choisir l’affichage.'),('Le footer','Le footer est une sous-vue.'),('Le navigateur en exécutant le SQL','Le SQL reste côté serveur.'),('La feuille CSS','Elle ne coordonne pas les données.')],'Le schéma relie point d’entrée, sous-contrôleur, modèle puis présentation.')
Q(4,31,'Modèle','Le modèle transmet-il ses données préparées au contrôleur ?', [('Oui','Le contrôleur les fournit ensuite à la vue dans le parcours décrit.'),('Non, il doit toujours afficher tout le HTML','Le cours sépare données et affichage.')],'Le modèle recherche et organise les informations.','facile',kind='vrai-faux')
Q(4,32,'Démarche','Quelle est la première étape de la démarche ?', [('Définir les cas d’utilisation','On commence par les fonctionnalités attendues.'),('Écrire tous les INSERT dans les vues','Cela contredit MVC.'),('Créer uniquement le footer','La conception commence avant ce détail de présentation.'),('Supprimer le contrôleur principal','Il sera écrit à l’étape 4.')],'La démarche commence par les besoins de l’application.','facile')
Q(4,[32,34],'Démarche','Que fait-on après avoir défini les cas d’utilisation ?', [('Imaginer les vues externes','C’est la deuxième étape.'),('Ignorer les pages à afficher','Les vues externes sont explicitement étudiées.'),('Supprimer toute architecture de répertoires','L’architecture est la troisième étape.'),('Déployer avant de coder les fonctionnalités','Ce n’est pas l’ordre du cours.')],'Besoins puis écrans, puis architecture et code.')
Q(4,[32,35,36],'Démarche','Quel ordre respecte les étapes centrales du cours ?', [('Architecture, contrôleur principal, cas d’utilisation codés','Ce sont les étapes 3, 4 et 5.'),('Cas codés, suppression des vues, besoins','Cela inverse la démarche.'),('Contrôleur principal, besoins, architecture','Les besoins et l’architecture le précèdent.'),('Base effacée, CSS, footer','Ce n’est pas la démarche proposée.')],'La structure précède l’implémentation détaillée.')
Q(4,33,'Cas d’utilisation','Quel élément constitue un cas d’utilisation de gestion des étudiants ?', [('Ajouter un étudiant','C’est une fonctionnalité attendue par l’utilisateur.'),('Le nom de la variable $fichier','C’est un détail d’implémentation.'),('La couleur du symbole dollar','Ce n’est pas une fonctionnalité de gestion.'),('Le mot-clé private','C’est une syntaxe de visibilité.')],'Consulter, ajouter, modifier et supprimer sont les exemples cités.','facile')
Q(4,37,'Valeur par défaut','Sans paramètre controleur, quelle valeur est choisie ?', [('etudiant','C’est la valeur de droite du coalescent.'),('controleur','C’est le nom de la clé, pas le défaut.'),('null','Le défaut empêche justement ce résultat ici.'),('index.php','C’est le fichier exécuté, pas la valeur de la variable.')],'?? fournit une valeur de repli.',code='$controleur = $_GET["controleur"] ?? "etudiant";')
Q(4,37,'Chemin','Avec $controleur = "etudiant", quel chemin est construit ?', [('controleurs/etudiant.php','Les trois chaînes sont concaténées.'),('vues/etudiant.php','Le dossier indiqué est controleurs.'),('controleurs/$controleur.php au sens littéral','La variable est utilisée hors d’une chaîne simple.'),('etudiant/controleurs.php','L’ordre de concaténation n’est pas inversé.')],'Le point concatène dossier, nom et extension.',code='$fichier = "controleurs/" . $controleur . ".php";')
Q(4,37,'Fichiers','Que teste file_exists($fichier) ?', [('L’existence du chemin','La fonction ne valide pas à elle seule le choix du contrôleur.'),('La présence d’un étudiant dans la base','Ce n’est pas une requête.'),('Le succès d’une insertion SQL','Aucun INSERT n’est testé.'),('Le rôle administrateur de l’utilisateur','L’existence du fichier n’est pas une autorisation.')],'Le cours l’emploie avant include ; existence et autorisation ne sont pas synonymes.')
Q(4,37,'Fichiers','Que fait include($fichier) ici ?', [('Charge et exécute le fichier PHP ciblé','Le sous-contrôleur prend alors le relais.'),('Effectue nécessairement une redirection HTTP','include charge un fichier côté serveur.'),('Télécharge automatiquement le fichier sur le poste','Ce n’est pas son rôle.'),('Compare deux chemins sans exécution','Le test est fait par file_exists.')],'Le mot « redirection » du cours désigne ici une orientation interne, pas un en-tête HTTP.')
Q(4,38,'Navigation','Quelle URL respecte le point d’entrée du cours ?', [('index.php?controleur=etudiant','La demande passe par le contrôleur principal.'),('controleurs/etudiant.php directement','Cela contourne le point d’entrée prévu.'),('modeles/etudiant.php directement','Le modèle n’est pas une page de navigation.'),('vues/layout.php comme unique traitement','Cela contourne la coordination prévue.')],'Le navigateur appelle index.php avec un choix de contrôleur.','facile')
Q(4,39,'Ajout','Pour ajouter un étudiant, qui réalise l’insertion dans la base ?', [('Le modèle','Le contrôleur lui transmet les informations.'),('La vue seule','La vue présente le résultat.'),('Le menu CSS','Il ne réalise pas l’insertion.'),('Le label du champ','Il ne traite aucune donnée.')],'Contrôleur : recevoir ; modèle : insérer ; vue : afficher.','facile')
Q(4,41,'Films','Quelles fonctionnalités sont demandées pour le catalogue de films ?', [('Consulter un film et filtrer par catégorie','Ces deux consultations sont demandées.'),('Ajouter un film','Cette fonctionnalité est explicitement demandée.'),('Payer une location','L’exercice ne décrit pas de paiement.'),('Envoyer un film en streaming','Ce service n’est pas au programme de l’exercice.')],'La banque reste centrée sur le catalogue de données.','intermediaire',[0,1],'multiple')
Q(4,43,'Modèle films','Quelle méthode du modèle sélectionne un seul film ?', [('obtenirUnFilm($id)','Elle recherche par identifiant.'),('obtenirLesFilms()','Elle récupère tous les films.'),('ajouterFilm($donnees)','Elle insère un nouveau film.'),('obtenirFilmsParCategorie($idCategorie)','Elle filtre plusieurs films par catégorie.')],'Les noms expriment les opérations de données.','facile')
Q(4,43,'Modèle films','Quelle méthode choisir pour le filtre de catégorie ?', [('obtenirFilmsParCategorie($idCategorie)','La catégorie est le critère reçu.'),('obtenirUnFilm($idCategorie)','Cette méthode attend l’identifiant d’un film.'),('ajouterFilm($idCategorie)','Le filtre ne doit pas créer un film.'),('obtenirLesFilms() sans filtrage','La liste entière ne réalise pas le filtre demandé.')],'Identifiant de film et identifiant de catégorie ne sont pas interchangeables.')
Q(4,44,'Vues films','Dans quelle sous-vue placer le titre commun « Catalogue de films » ?', [('header.php','L’énoncé y place le titre commun.'),('connexion.php','Ce fichier sert à la connexion.'),('film.php du modèle','Il gère les données.'),('c_films.php comme texte HTML principal','L’exercice le réserve au sous-contrôleur.')],'L’exercice répartit header, menu et footer.','facile')
Q(4,45,'Vues films','Quelles informations sont demandées dans liste_films.php ?', [('Titre, réalisateur et année','Ce sont les colonnes citées pour la liste.'),('Uniquement l’identifiant de connexion SQL','Ce n’est pas une donnée à présenter.'),('Uniquement un formulaire de connexion','Ce n’est pas le rôle de cette liste.'),('Tous les scripts SQL de création','Ils ne sont pas l’affichage attendu.')],'La vue de liste fournit aussi un lien vers les détails.','facile')
Q(4,47,'Formulaire films','D’où proviennent les choix de la liste déroulante Catégorie ?', [('De la base, via le modèle et le contrôleur','L’énoncé demande une liste alimentée par les données.'),('Du mot de passe PDO','Ce n’est pas une catégorie.'),('Du nom du fichier CSS','Ce n’est pas une source de catégories.'),('Du destructeur de chaque film','Ce n’est pas le rôle d’un destructeur.')],'Le contrôleur doit préparer les catégories avant la vue.')
Q(4,47,'Formulaire films','À qui le formulaire doit-il transmettre les données pour traitement ?', [('Au contrôleur','Il reçoit la demande puis sollicite le modèle.'),('Directement à un fichier SQL public','Le formulaire doit passer par l’application.'),('Au footer seulement','Le footer n’est pas le traitement.'),('À la feuille de style','CSS ne traite pas le formulaire.')],'Le parcours d’ajout respecte la coordination MVC.','facile')
Q(4,48,'Actions films','Quelle différence existe entre ajouter et enregistrer ?', [('ajouter affiche le formulaire ; enregistrer traite les données','Le switch distingue la préparation et la soumission.'),('Les deux doivent toujours supprimer un film','Aucune suppression n’est décrite pour ces actions.'),('ajouter lit un détail ; enregistrer ne fait rien','Cela ne correspond pas à l’énoncé.'),('ajouter est un fichier CSS ; enregistrer est une base','Ce sont les noms d’actions du contrôleur.')],'Après enregistrement, l’exercice demande un retour vers la liste.')
Q(4,[49,50],'Tests','Quels scénarios de vérification sont demandés pour le catalogue ?', [('Consultation de liste et détails','C’est le premier scénario.'),('Filtre par catégorie et ajout','Ce sont les deux autres scénarios.'),('Changement obligatoire du SGBD','Ce n’est pas un scénario demandé.'),('Paiement en ligne','Ce n’est pas une fonctionnalité du catalogue.')],'Les tests couvrent les trois parcours décrits.','intermediaire',[0,1],'multiple')
# 60 EXERCICES — la validation reste une auto-évaluation explicite, sans fausse exécution.
C(1,4,'Variables','Déclare $nom avec la chaîne "Anna" et $age avec l’entier 20.','$nom = "Anna";\n$age = 20;',['Ligne 1 : affecte la chaîne Anna à $nom.','Ligne 2 : affecte l’entier 20 à $age.'],'Une variable commence par $.',['Oublier $ ou le point-virgule.','Écrire "20" au lieu d’un entier.'],['$nom contient Anna.','$age contient l’entier 20.','Les deux affectations sont valides.'],'facile',["$nom = 'Anna';\n$age = 20;"])
C(1,3,'Affichage','$nom est déjà défini. Affiche « Bonjour » suivi d’un espace et de sa valeur.','echo "Bonjour " . $nom;',['Ligne 1 : concatène le texte, son espace final et $nom, puis les affiche.'],'Le point assemble deux chaînes.',['Oublier l’espace.','Mettre $nom entre apostrophes dans la chaîne.'],['Bonjour est affiché.','La valeur de $nom est affichée.','Un espace sépare les deux.'],'facile',['echo "Bonjour $nom";'])
C(1,[5,6],'Conditions','À partir de $age déjà défini, affiche "Majeur" si $age >= 18, sinon "Mineur".','if ($age >= 18) {\n    echo "Majeur";\n} else {\n    echo "Mineur";\n}',['Ligne 1 : teste la borne de 18 ans incluse.','Ligne 2 : affiche Majeur si le test est vrai.','Lignes 3–5 : la branche else affiche Mineur sinon.'],'Deux branches exclusives : if et else.',['Écrire > au lieu de >=.','Utiliser = au lieu d’une comparaison.'],['18 est classé majeur.','Les âges inférieurs sont classés mineurs.','Une seule branche s’affiche.'],'facile')
C(1,[7,10],'Conditions','Avec $note déjà définie, affiche "Très bien" à partir de 16, "Admis" de 10 à moins de 16, sinon "Non admis".','if ($note >= 16) {\n    echo "Très bien";\n} elseif ($note >= 10) {\n    echo "Admis";\n} else {\n    echo "Non admis";\n}',['Lignes 1–2 : traite les notes >= 16.','Lignes 3–4 : traite les notes >= 10 restantes.','Lignes 5–7 : traite les notes < 10.'],'Teste d’abord le seuil le plus élevé.',['Tester >= 10 avant >= 16 dans la même chaîne.','Oublier la borne 10 ou 16.'],['16 et plus donnent Très bien.','10 à moins de 16 donnent Admis.','Moins de 10 donne Non admis.'])
C(1,12,'Boucles','Affiche les entiers de 1 à 5, chacun suivi de <br>, avec une boucle for.','for ($i = 1; $i <= 5; $i++) {\n    echo $i . "<br>";\n}',['Ligne 1 : initialise, teste puis incrémente le compteur.','Ligne 2 : affiche le nombre suivi du saut HTML.','Ligne 3 : ferme le bloc.'],'La borne supérieure doit être incluse.',['Commencer à 0.','Oublier l’incrémentation.'],['La boucle est un for.','Les valeurs sont 1, 2, 3, 4, 5.','Chaque valeur est suivie de <br>.'],'facile')
C(1,13,'Boucles','Écris une boucle while affichant de 1 à 3, sans séparateur. Initialise toi-même le compteur.','$i = 1;\nwhile ($i <= 3) {\n    echo $i;\n    $i++;\n}',['Ligne 1 : initialise à 1.','Ligne 2 : teste la borne incluse.','Ligne 3 : affiche.','Ligne 4 : fait progresser le compteur.','Ligne 5 : termine le bloc.'],'Le compteur doit évoluer dans la boucle.',['Boucle infinie sans $i++.','Borne < 3 au lieu de <= 3.'],['Le compteur commence à 1.','La sortie est 123.','La boucle se termine.'])
C(1,20,'Tableaux','Crée $fruits contenant "Pomme", "Banane", "Orange", puis remplace le deuxième fruit par "Fraise".','$fruits = ["Pomme", "Banane", "Orange"];\n$fruits[1] = "Fraise";',['Ligne 1 : crée le tableau indexé.','Ligne 2 : remplace l’élément d’indice 1.'],'Le premier indice implicite vaut 0.',['Remplacer l’indice 2.','Recréer le tableau avec un seul fruit.'],['Le tableau possède trois éléments.','Pomme et Orange sont conservés.','Le deuxième élément devient Fraise.'],'facile')
C(1,[21,23],'Tableaux','Crée $produits associant "Clavier" à 25 et "Souris" à 15, puis affiche le prix du clavier.','$produits = ["Clavier" => 25, "Souris" => 15];\necho $produits["Clavier"];',['Ligne 1 : associe chaque clé textuelle à son prix.','Ligne 2 : lit et affiche la valeur liée à Clavier.'],'Utilise => pour associer clé et valeur.',['Utiliser -> dans le tableau.','Changer la casse de la clé lors de l’accès.'],['Les deux clés sont correctes.','Leurs valeurs numériques sont 25 et 15.','Le prix 25 est affiché.'],'facile')
C(1,15,'Boucles','$produits est un tableau associatif nom => prix. Affiche chaque nom puis " : " puis son prix suivi de <br>.','foreach ($produits as $nom => $prix) {\n    echo $nom . " : " . $prix . "<br>";\n}',['Ligne 1 : récupère clé et valeur à chaque tour.','Ligne 2 : assemble l’affichage demandé.','Ligne 3 : ferme le parcours.'],'foreach peut recevoir la clé et la valeur.',['Inverser $nom et $prix.','Ne récupérer que la valeur.'],['Toutes les entrées sont parcourues.','Nom et prix sont affichés dans cet ordre.','Le séparateur et <br> sont présents.'])
C(1,[17,23],'Accumulation','$produits contient des prix numériques. Calcule leur somme dans $total sans fonction de somme prédéfinie.','$total = 0;\nforeach ($produits as $prix) {\n    $total = $total + $prix;\n}',['Ligne 1 : initialise l’accumulateur avant la boucle.','Ligne 2 : parcourt les prix.','Ligne 3 : ajoute le prix courant au total.','Ligne 4 : ferme le parcours.'],'Il faut conserver le total des tours précédents.',['Réinitialiser $total dans la boucle.','Affecter seulement $prix à $total.'],['Le total est initialisé à zéro.','Chaque prix est ajouté une fois.','$total contient la somme finale.'],alternatives=['$total = 0;\nforeach ($produits as $prix) { $total += $prix; }'])
C(1,27,'Fonctions','Crée additionner($a, $b) qui renvoie leur somme sans l’afficher.','function additionner($a, $b) {\n    return $a + $b;\n}',['Ligne 1 : déclare les deux paramètres.','Ligne 2 : renvoie la somme à l’appelant.','Ligne 3 : ferme la fonction.'],'Le résultat doit être réutilisable par l’appelant.',['Utiliser echo au lieu de return.','Concaténer au lieu d’additionner.'],['La fonction porte le nom demandé.','Elle accepte deux paramètres.','Elle renvoie leur somme sans affichage.'],'facile')
C(1,28,'Fonctions','Crée calculerMoyenne($a, $b, $c), puis stocke la moyenne de 12, 15 et 9 dans $moyenne.','function calculerMoyenne($a, $b, $c) {\n    return ($a + $b + $c) / 3;\n}\n$moyenne = calculerMoyenne(12, 15, 9);',['Ligne 1 : déclare les paramètres.','Ligne 2 : divise la somme complète par 3.','Ligne 3 : ferme la fonction.','Ligne 4 : récupère le résultat, 12.'],'Les parenthèses portent sur la somme des trois notes.',['Diviser seulement la troisième note.','Afficher la moyenne sans la renvoyer.'],['Trois paramètres sont utilisés.','La somme complète est divisée par trois.','$moyenne reçoit 12.'])
C(1,36,'GET','Si le paramètre GET "mot" existe et n’est pas null, affiche sa valeur échappée pour le HTML avec ENT_QUOTES et UTF-8.','if (isset($_GET["mot"])) {\n    echo htmlspecialchars($_GET["mot"], ENT_QUOTES, "UTF-8");\n}',['Ligne 1 : vérifie l’existence et la non-nullité.','Ligne 2 : échappe puis affiche la valeur.','Ligne 3 : ferme le test.'],'Combine isset et htmlspecialchars.',['Utiliser $_POST au lieu de $_GET.','Afficher la saisie brute.'],['La bonne superglobale et la clé mot sont utilisées.','L’existence est vérifiée.','L’échappement ENT_QUOTES / UTF-8 précède l’affichage.'])
C(1,[42,43],'Validation','Récupère $prix depuis POST (défaut chaîne vide), retire ses espaces extérieurs puis affecte à $valide un booléen vrai uniquement pour un nombre strictement positif.','$prix = trim($_POST["prix"] ?? "");\n$valide = is_numeric($prix) && $prix > 0;',['Ligne 1 : récupère et nettoie une valeur avec défaut.','Ligne 2 : exige un nombre et une valeur > 0.'],'Le prix nul doit être rejeté dans cet énoncé.',['Tester seulement isset.','Accepter zéro avec >= 0.'],['L’absence de champ est prévue.','Les espaces extérieurs sont retirés.','La validation combine numericité et stricte positivité.'],'difficile')
C(1,38,'POST','Si les deux champs POST nom et email existent et sont non null, stocke leurs valeurs échappées pour HTML dans $nom et $email.','if (isset($_POST["nom"]) && isset($_POST["email"])) {\n    $nom = htmlspecialchars($_POST["nom"], ENT_QUOTES, "UTF-8");\n    $email = htmlspecialchars($_POST["email"], ENT_QUOTES, "UTF-8");\n}',['Ligne 1 : exige les deux champs avec &&.','Ligne 2 : prépare nom pour le HTML.','Ligne 3 : prépare email pour le HTML.','Ligne 4 : ferme le test.'],'Les deux clés doivent être testées.',['Utiliser || au lieu de &&.','Croire que POST réalise l’échappement.'],['Les deux clés sont vérifiées.','Les deux valeurs POST sont lues.','Les deux valeurs sont échappées.'])
# Chapitre 2 : les méthodes sont des fragments à placer dans la classe indiquée.
C(2,5,'Visibilité','Déclare une classe Personne avec num privé, nom protégé et societe public.','class Personne {\n    private $num;\n    protected $nom;\n    public $societe;\n}',['Ligne 1 : déclare la classe.','Ligne 2 : limite num à la classe.','Ligne 3 : permet l’accès à nom dans la hiérarchie.','Ligne 4 : expose societe.','Ligne 5 : ferme la classe.'],'Associe chaque attribut à la visibilité demandée.',['Inverser private et protected.','Oublier $ dans la déclaration.'],['La classe porte le bon nom.','Les trois attributs existent.','Chaque visibilité correspond à l’énoncé.'],'facile')
C(2,7,'Encapsulation','Dans Personne, écris le getter public getNum() pour l’attribut privé num.','public function getNum() {\n    return $this->num;\n}',['Ligne 1 : déclare la méthode publique.','Ligne 2 : renvoie l’attribut de l’objet.','Ligne 3 : ferme la méthode.'],'Le getter renvoie au lieu d’afficher.',['Oublier $this->.','Utiliser echo.'],['Le nom getNum est exact.','La méthode est publique.','Elle renvoie $this->num.'],'facile',context='À placer à l’intérieur de la classe Personne.')
C(2,7,'Encapsulation','Dans Personne, écris setNum($nvNum) qui modifie le numéro de l’objet.','public function setNum($nvNum) {\n    $this->num = $nvNum;\n}',['Ligne 1 : reçoit la nouvelle valeur.','Ligne 2 : modifie la propriété de l’instance.','Ligne 3 : ferme la méthode.'],'La propriété est distincte du paramètre.',['Modifier uniquement $num local.','Écrire == au lieu de =.'],['Le paramètre est reçu.','La propriété num est affectée.','Le setter est public.'],'facile',context='À placer à l’intérieur de Personne.')
C(2,8,'Instance','Instancie Personne sans argument dans $p, donne-lui le numéro 123 avec setNum puis affiche getNum.','$p = new Personne();\n$p->setNum(123);\necho $p->getNum();',['Ligne 1 : crée l’instance.','Ligne 2 : appelle le setter.','Ligne 3 : affiche la valeur renvoyée.'],'Les méthodes d’objet utilisent ->.',['Lire directement un attribut privé.','Utiliser le point pour appeler une méthode.'],['$p est une nouvelle Personne.','setNum reçoit 123.','Le résultat de getNum est affiché.'],'facile',context='La classe Personne avec constructeur sans argument et accesseurs existe déjà.')
C(2,11,'Constructeur','Dans Personne, écris un constructeur recevant $num, $nom, $societe et initialisant les trois propriétés correspondantes.','public function __construct($num, $nom, $societe) {\n    $this->num = $num;\n    $this->nom = $nom;\n    $this->societe = $societe;\n}',['Ligne 1 : nom magique exact et trois paramètres.','Lignes 2–4 : affectent chaque paramètre à sa propriété.','Ligne 5 : ferme le constructeur.'],'Deux underscores précèdent construct.',['Nommer la méthode construct.','N’affecter que les variables locales.'],['Le constructeur est correctement nommé.','Les trois paramètres sont reçus.','Les trois propriétés sont initialisées.'],context='Fragment interne de Personne, propriétés déjà déclarées.')
C(2,13,'Arguments','Dans un constructeur appelé avec numéro, nom, société, récupère le nombre d’arguments dans $n et la société dans $societe.','$n = func_num_args();\n$societe = func_get_arg(2);',['Ligne 1 : compte les arguments reçus.','Ligne 2 : lit le troisième argument à l’indice 2.'],'Le premier argument a l’indice zéro.',['Utiliser l’indice 3.','Confondre count et extraction.'],['func_num_args est appelé dans le constructeur.','Le nombre est stocké dans $n.','L’argument d’indice 2 est stocké dans $societe.'],context='Ces lignes se placent dans le corps du constructeur.')
C(2,14,'Arguments','Complète un fragment de constructeur : si deux arguments sont reçus, initialise num et nom depuis ces arguments et societe à "inconnu".','if (func_num_args() == 2) {\n    $this->num = func_get_arg(0);\n    $this->nom = func_get_arg(1);\n    $this->societe = "inconnu";\n}',['Ligne 1 : sélectionne le format à deux arguments.','Lignes 2–3 : lisent les arguments aux bons indices.','Ligne 4 : fixe le défaut.','Ligne 5 : ferme le test.'],'Tu peux traiter uniquement le cas demandé avec if.',['Utiliser 1 et 2 comme indices.','Chercher un troisième argument inexistant.'],['Le format deux arguments est testé.','num et nom utilisent 0 et 1.','societe reçoit inconnu.'],context='Fragment du corps de __construct().')
C(2,18,'Méthodes','Dans Voiture, écris calculerPrixLocation($nbJours) qui renvoie prixJournalier multiplié par la durée.','public function calculerPrixLocation($nbJours) {\n    return $this->prixJournalier * $nbJours;\n}',['Ligne 1 : reçoit le nombre de jours.','Ligne 2 : renvoie le coût total.','Ligne 3 : ferme la méthode.'],'Le tarif appartient à l’objet courant.',['Additionner tarif et durée.','Afficher sans retourner.'],['La durée est un paramètre.','Le tarif vient de $this->prixJournalier.','Le produit est renvoyé.'],'facile',context='À placer dans Voiture ; prixJournalier existe déjà.')
C(2,22,'Héritage','Déclare Etudiant héritant de Personne et ajoute formation comme propriété privée.','class Etudiant extends Personne {\n    private $formation;\n}',['Ligne 1 : déclare l’héritage avec extends.','Ligne 2 : ajoute la donnée propre à Etudiant.','Ligne 3 : ferme la classe.'],'Le mot-clé est extends.',['Utiliser parent à la place de extends.','Oublier la visibilité demandée.'],['La classe est Etudiant.','Elle étend Personne.','formation est privé.'],'facile',context='Personne existe déjà.')
C(2,21,'Héritage','Dans Etudiant, écris le constructeur ($nom, $formation), appelle celui de Personne avec $nom puis initialise formation.','public function __construct($nom, $formation) {\n    parent::__construct($nom);\n    $this->formation = $formation;\n}',['Ligne 1 : reçoit les deux informations.','Ligne 2 : initialise la partie Personne.','Ligne 3 : initialise l’attribut de la fille.','Ligne 4 : ferme le constructeur.'],'L’appel parent utilise ::.',['Rappeler $this->__construct.','Omettre la partie mère.'],['Les deux paramètres sont reçus.','parent::__construct reçoit $nom.','formation est affecté sur l’objet.'],context='Fragment dans class Etudiant extends Personne ; formation existe déjà.')
C(2,30,'Héritage','Dans Formateur::afficherInfos, appelle l’affichage hérité puis affiche la spécialité de l’objet.','public function afficherInfos() {\n    parent::afficherInfos();\n    echo $this->specialite;\n}',['Ligne 1 : redéfinit l’affichage.','Ligne 2 : réutilise l’affichage de la mère.','Ligne 3 : ajoute l’information spécifique.','Ligne 4 : ferme la méthode.'],'Utilise parent pour la version héritée.',['Appeler récursivement $this->afficherInfos().','Utiliser une variable locale specialite.'],['La méthode est publique.','La méthode parent est appelée.','La spécialité de l’instance est affichée.'],context='Dans class Formateur extends Utilisateur ; specialite et la méthode parent existent.')
C(2,24,'Destructeur','Dans une classe, écris un destructeur affichant "Destruction de l’objet".','public function __destruct() {\n    echo "Destruction de l’objet";\n}',['Ligne 1 : déclare le destructeur magique.','Ligne 2 : affiche le message.','Ligne 3 : ferme la méthode.'],'Le nom magique commence par deux underscores.',['Écrire __destroy.','Ajouter des arguments obligatoires au destructeur.'],['Le nom est __destruct.','Aucun paramètre n’est imposé.','Le message est affiché.'],'facile',context='Fragment à placer à l’intérieur d’une classe.')
C(2,27,'Statique','Dans Personne, déclare la planète commune privée "Terre" et une méthode statique publique donnePlanete qui la renvoie.','private static $planete = "Terre";\npublic static function donnePlanete() {\n    return self::$planete;\n}',['Ligne 1 : déclare la propriété de classe.','Ligne 2 : déclare le getter statique.','Ligne 3 : lit la propriété avec self::$.','Ligne 4 : ferme le getter.'],'Une propriété statique garde son $ après ::.',['Écrire self::planete.','Utiliser $this dans la méthode statique.'],['La propriété est privée et statique.','La méthode est publique et statique.','La propriété est renvoyée avec une syntaxe valide.'],context='Fragment à l’intérieur de Personne.')
C(2,28,'Statique','Affiche la valeur renvoyée par donnePlanete(), méthode publique statique de Personne.','echo Personne::donnePlanete();',['Ligne 1 : appelle la méthode de classe avec :: puis affiche son retour.'],'Aucun objet ne doit être créé pour cet appel.',['Utiliser Personne->.','Oublier les parenthèses de l’appel.'],['Personne est la classe appelée.','L’opérateur est ::.','Le résultat est affiché.'],'facile')
C(2,31,'Compteur','Dans Utilisateur, déclare nombreUtilisateurs privé statique initialisé à zéro et getNombreUtilisateurs() public statique qui le renvoie.','private static $nombreUtilisateurs = 0;\npublic static function getNombreUtilisateurs() {\n    return self::$nombreUtilisateurs;\n}',['Ligne 1 : initialise le compteur commun.','Ligne 2 : expose un getter de classe.','Ligne 3 : renvoie sans modifier le compteur.','Ligne 4 : ferme la méthode.'],'Un getter ne doit pas incrémenter le total.',['Utiliser $this.','Incrémenter au moment de la lecture.'],['Le compteur commence à zéro.','Il est privé statique.','Le getter public statique renvoie sa valeur.'],context='Fragment interne de Utilisateur ; l’incrémentation dans le constructeur est hors de cet exercice.')
C(3,20,'DAO instance','Déclare PersonneDAO avec une propriété privée laConnexion, initialisée dans son constructeur par GestionConnexion::getConnexion().','class PersonneDAO {\n    private $laConnexion;\n    public function __construct() {\n        $this->laConnexion = GestionConnexion::getConnexion();\n    }\n}',['Lignes 1–2 : déclarent le DAO et son attribut.','Ligne 3 : déclare le constructeur.','Ligne 4 : conserve la connexion dans l’objet.','Lignes 5–6 : ferment les blocs.'],'La connexion doit rester accessible aux autres méthodes.',['Laisser la connexion dans une variable locale.','Instancier directement GestionConnexion dont le constructeur est privé.'],['Le DAO est déclaré.','La connexion est une propriété privée.','Le constructeur affecte cette propriété avec le service technique.'],'facile')
C(3,19,'Connexion','Obtiens la connexion partagée et conserve-la dans $pdo.','$pdo = GestionConnexion::getConnexion();',['Ligne 1 : appelle le point d’accès statique et conserve son retour.'],'L’appel se fait sur la classe technique.',['Utiliser new GestionConnexion.','Oublier l’affectation.'],['L’appel vise GestionConnexion.','getConnexion est appelé avec ::.','$pdo reçoit le résultat.'],'facile')
C(3,19,'PDO','Écris l’instruction créant $pdo pour MySQL sur localhost, base nomBase, identifiant login et mot de passe mdp.','$pdo = new PDO("mysql:host=localhost;dbname=nomBase", "login", "mdp");',['Ligne 1 : crée PDO avec DSN MySQL, identifiant et mot de passe.'],'Le DSN contient le pilote, host et dbname.',['Inverser base et hôte.','Oublier new.'],['Le DSN cible MySQL et localhost.','La base est nomBase.','login et mdp sont passés dans cet ordre.'])
C(3,19,'Singleton','Dans GestionConnexion, déclare les propriétés statiques privées _instance (null) et laConnexion.','private static $_instance = null;\nprivate static $laConnexion;',['Ligne 1 : initialise la référence de contrôle.','Ligne 2 : prévoit l’emplacement de PDO.'],'Les deux valeurs sont à portée de classe.',['Créer des propriétés d’instance.','Oublier $ dans le nom.'],['Les deux propriétés existent.','Elles sont privées statiques.','_instance est initialisée à null.'],'facile',context='Fragment à l’intérieur de GestionConnexion.')
C(3,19,'Singleton','Dans getConnexion(), instancie GestionConnexion uniquement si self::$_instance est null.','if (is_null(self::$_instance)) {\n    self::$_instance = new GestionConnexion();\n}',['Ligne 1 : teste l’absence d’instance.','Ligne 2 : initialise seulement dans ce cas.','Ligne 3 : ferme le test.'],'La création reste interne à la classe.',['Instancier à chaque appel sans test.','Utiliser $this dans une méthode statique.'],['La nullité est testée.','L’instanciation est conditionnelle.','L’instance est conservée dans la propriété statique.'],context='Fragment de méthode statique à l’intérieur de GestionConnexion.')
C(3,19,'Singleton','Écris getConnexion() public statique complet à partir de _instance, laConnexion et du constructeur privé déjà présents.','public static function getConnexion() {\n    if (is_null(self::$_instance)) {\n        self::$_instance = new GestionConnexion();\n    }\n    return self::$laConnexion;\n}',['Ligne 1 : expose un accès de classe.','Lignes 2–4 : initialisent si nécessaire.','Ligne 5 : renvoie PDO.','Ligne 6 : ferme la méthode.'],'L’instance de contrôle et la connexion renvoyée sont distinctes.',['Renvoyer _instance à la place de laConnexion.','Créer systématiquement une nouvelle connexion.'],['La méthode est publique statique.','La création est protégée par le test.','La connexion est renvoyée.'],'difficile',context='Méthode interne de GestionConnexion ; le constructeur crée self::$laConnexion.')
C(3,19,'Connexion','Écris la méthode publique statique liberer qui remet _instance et laConnexion à null dans GestionConnexion.','public static function liberer() {\n    self::$_instance = null;\n    self::$laConnexion = null;\n}',['Ligne 1 : déclare l’opération statique.','Lignes 2–3 : enlèvent les références conservées.','Ligne 4 : ferme la méthode.'],'Ne remets pas seulement une variable locale à null.',['Utiliser self::laConnexion sans $.','Croire que cela supprime des tables.'],['La méthode est publique statique.','_instance est remise à null.','laConnexion est remise à null.'],context='Fragment interne de GestionConnexion.')
C(3,33,'Stratégie 2','Crée une soirée dans $soiree avec "23/03/2021", "Observer La Lune", 30, crée son DAO dans $dao puis appelle creer avec la soirée.','$soiree = new Soiree("23/03/2021", "Observer La Lune", 30);\n$dao = new SoireeDAO();\n$dao->creer($soiree);',['Ligne 1 : construit l’objet métier.','Ligne 2 : construit le DAO.','Ligne 3 : demande la persistance depuis le programme.'],'Le programme connaît les deux objets.',['Utiliser le point pour appeler creer.','Passer le DAO à la place de la soirée.'],['La soirée contient les trois valeurs.','Le DAO est instancié.','creer reçoit l’objet métier.'],'facile',context='Soiree et SoireeDAO existent avec les signatures du cours.')
C(3,31,'Stratégie 1','Dans Soiree, écris sauvegardeToi() qui renvoie le résultat de creer($this) sur le DAO conservé dans objSoireeDAO.','public function sauvegardeToi() {\n    return $this->objSoireeDAO->creer($this);\n}',['Ligne 1 : expose l’action de sauvegarde métier.','Ligne 2 : transmet l’objet courant à son DAO et renvoie le résultat.','Ligne 3 : ferme la méthode.'],'Le DAO doit recevoir l’objet courant.',['Utiliser objSoireeDAO sans $this->.','Utiliser . au lieu de ->.'],['La méthode est définie.','Le DAO de l’objet est appelé.','$this est transmis et le résultat renvoyé.'],context='Fragment de Soiree ; objSoireeDAO est une propriété déjà initialisée.')
C(3,26,'Finders','$dao existe. Récupère la personne d’id 12 dans $personne avec findById puis toute la table dans $personnes avec findAll.','$personne = $dao->findById(12);\n$personnes = $dao->findAll();',['Ligne 1 : recherche une occurrence par identifiant.','Ligne 2 : récupère la collection entière.'],'Un finder retourne les données recherchées.',['Inverser findAll et findById.','Oublier de stocker les retours.'],['findById reçoit 12.','Son retour est stocké dans $personne.','findAll est stocké dans $personnes.'],'facile')
C(3,[23,14],'Create','Dans SoireeDAO, écris creer($soiree) qui récupère date, nature et places dans $date, $nature et $places avec les getters du cours. Pas de SQL demandé.','public function creer($soiree) {\n    $date = $soiree->getLaDateSoiree();\n    $nature = $soiree->getLaNature();\n    $places = $soiree->getLeNbPlaces();\n}',['Ligne 1 : reçoit l’objet métier.','Lignes 2–4 : extraient les informations à enregistrer.','Ligne 5 : ferme le fragment de méthode.'],'Les informations sont accessibles par les méthodes publiques.',['Accéder directement aux attributs privés.','Oublier les parenthèses des getters.'],['La méthode reçoit un objet.','Les trois getters corrects sont appelés.','Les valeurs sont stockées dans les variables demandées.'],context='Méthode interne de SoireeDAO ; exercice limité à la préparation des données.')
C(3,21,'DAO statique','La classe PersonneDAO définit une méthode publique statique inserer. Appelle-la avec $personne et conserve son résultat dans $succes.','$succes = PersonneDAO::inserer($personne);',['Ligne 1 : utilise la forme statique et conserve le retour.'],'Pas besoin de créer un objet pour cette forme de DAO.',['Utiliser PersonneDAO->.','Oublier de passer $personne.'],['L’appel est statique.','L’objet métier est transmis.','Le résultat est stocké.'],'facile')
C(3,27,'Update','Le contrat fourni est $dao->modifier($id, $nom). Modifie la personne 12 avec le nom "Anna" et conserve le retour dans $succes.','$succes = $dao->modifier(12, "Anna");',['Ligne 1 : transmet identifiant puis nouvelle valeur et conserve le résultat.'],'L’identifiant cible la ligne à modifier.',['Inverser identifiant et nom.','Appeler creer au lieu de modifier.'],['La méthode est modifier.','Les arguments sont 12 puis Anna.','Le retour est stocké dans $succes.'],'facile',context='Le nom et la signature sont fournis par cet exercice ; ils illustrent la variante Update du cours.')
C(3,28,'Delete','Le DAO fournit supprimer($id). Supprime l’enregistrement d’id 12 et conserve son résultat dans $succes.','$succes = $dao->supprimer(12);',['Ligne 1 : appelle Delete avec l’identifiant et conserve le résultat.'],'Le paramètre identifie l’enregistrement, pas la classe.',['Passer le nom de la table à la place de 12.','Confondre destructeur PHP et suppression dans le stockage.'],['La méthode supprimer est utilisée.','L’identifiant 12 est transmis.','Le retour est conservé.'],'facile',context='La méthode supprimer($id) est déjà définie dans $dao.')
C(3,[14,33],'Correction','Corrige l’affectation locale $_db = GestionConnexion::getConnexion(); pour initialiser la propriété _db de l’objet DAO.','$this->_db = GestionConnexion::getConnexion();',['Ligne 1 : affecte la connexion à la propriété d’instance au lieu d’une variable locale.'],'L’attribut doit appartenir à l’objet courant.',['Écrire $this->$_db.','Laisser $_db comme variable locale.'],['La cible est $this->_db.','La méthode technique est appelée statiquement.','L’affectation est syntaxiquement valide.'],context='Cette instruction se place dans le constructeur du DAO.')
# Chapitre 4
C(4,37,'Routage','Lis le paramètre GET controleur dans $controleur ; choisis "etudiant" s’il est absent ou null.','$controleur = $_GET["controleur"] ?? "etudiant";',['Ligne 1 : lit la clé avec un défaut explicite.'],'Le coalescent est ??.',['Utiliser action comme clé.','Oublier le défaut.'],['La clé controleur est lue dans GET.','Le défaut est etudiant.','La valeur est stockée.'],'facile',["$controleur = isset($_GET['controleur']) ? $_GET['controleur'] : 'etudiant';"])
C(4,37,'Chemin','$controleur est déjà défini. Construis $fichier au format controleurs/NOM.php avec concaténation.','$fichier = "controleurs/" . $controleur . ".php";',['Ligne 1 : assemble dossier, nom et extension.'],'La concaténation PHP utilise le point.',['Oublier le slash.','Utiliser + pour concaténer.'],['Le dossier est controleurs/.','La valeur de la variable est insérée.','Le suffixe est .php.'],'facile',context='Exercice de concaténation du cours ; le choix du nom de contrôleur doit être contrôlé par l’application réelle.')
C(4,37,'Fichiers','$fichier désigne un chemin déjà choisi. S’il existe, inclus-le, sinon affiche "Contrôleur introuvable.".','if (file_exists($fichier)) {\n    include($fichier);\n} else {\n    echo "Contrôleur introuvable.";\n}',['Ligne 1 : teste le chemin.','Ligne 2 : charge le fichier existant.','Lignes 3–5 : prévoient le cas manquant.'],'file_exists teste ; include charge.',['Confondre include et redirection HTTP.','Croire que l’existence vaut autorisation d’accès.'],['L’existence est testée.','Le bon fichier est inclus.','Le cas absent affiche le message.'],context='Le chemin est déjà sélectionné parmi les contrôleurs de l’application.')
C(4,12,'Contrôleur','Dans le contrôleur, récupère les étudiants avec obtenirLesEtudiants($pdo) dans $etudiants puis inclus vues/liste_etudiants.php.','$etudiants = obtenirLesEtudiants($pdo);\ninclude("vues/liste_etudiants.php");',['Ligne 1 : obtient les données du modèle.','Ligne 2 : appelle la présentation une fois les données prêtes.'],'Le modèle est appelé avant la vue.',['Inclure la vue avant d’avoir les données.','Mettre SELECT dans la vue.'],['La fonction modèle reçoit $pdo.','Son retour est affecté à $etudiants.','La vue demandée est incluse ensuite.'],'facile')
C(4,8,'Modèle','Dans le modèle, lis toutes les lignes de etudiants avec query puis fetchAll, et conserve-les dans $etudiants. $pdo est connecté.','$sql = "SELECT * FROM etudiants";\n$resultat = $pdo->query($sql);\n$etudiants = $resultat->fetchAll();',['Ligne 1 : définit la lecture SQL fixe.','Ligne 2 : exécute cette lecture via PDO.','Ligne 3 : récupère les lignes.'],'La requête et sa récupération appartiennent au modèle.',['Appeler fetchAll sur la chaîne SQL.','Intervertir query et fetchAll.'],['La table etudiants est lue.','query est appelée sur PDO.','fetchAll est appelée sur le résultat.'])
C(4,10,'Vue','Dans une vue PHP, parcours $etudiants et affiche chaque nom échappé avec htmlspecialchars, suivi de <br>. Utilise la syntaxe à accolades.','foreach ($etudiants as $etudiant) {\n    echo htmlspecialchars($etudiant["nom"], ENT_QUOTES, "UTF-8") . "<br>";\n}',['Ligne 1 : parcourt les lignes fournies.','Ligne 2 : échappe et affiche le nom, suivi du saut HTML.','Ligne 3 : ferme la boucle.'],'Combine le parcours MVC et l’échappement du chapitre 1.',['Placer une requête SQL dans la boucle de la vue.','Afficher le nom brut.'],['Tous les étudiants sont parcourus.','La clé nom est affichée.','L’échappement précède l’affichage.'])
C(4,[17,19],'Layout','Dans layout.php, inclus dans l’ordre vues/header.php, vues/menu.php, vues/etudiants/liste.php, vues/footer.php.','include("vues/header.php");\ninclude("vues/menu.php");\ninclude("vues/etudiants/liste.php");\ninclude("vues/footer.php");',['Ligne 1 : affiche l’en-tête.','Ligne 2 : insère la navigation.','Ligne 3 : place la liste au centre.','Ligne 4 : termine par le pied de page.'],'L’ordre des inclusions suit celui de la page.',['Placer le footer avant le contenu.','Confondre controleurs et vues.'],['Les quatre sous-vues sont incluses.','Les chemins sont cohérents.','L’ordre demandé est respecté.'],'facile')
C(4,28,'Paramètres','Récupère le paramètre REQUEST action dans $action ; utilise "liste" par défaut.','$action = $_REQUEST["action"] ?? "liste";',['Ligne 1 : récupère la fonctionnalité demandée avec un repli.'],'Il s’agit de l’action, pas du nom du contrôleur.',['Lire controleur à la place.','Traiter REQUEST comme une fonction.'],['La superglobale est REQUEST.','La clé est action.','Le défaut est liste.'],'facile')
C(4,29,'Actions','Écris un switch sur $action : pour voirCategories, appelle $laConnexion->getLesCategories() dans $lesCategories, inclus vues/v_categories.php puis sors du switch.','switch ($action) {\n    case "voirCategories":\n        $lesCategories = $laConnexion->getLesCategories();\n        include("vues/v_categories.php");\n        break;\n}',['Ligne 1 : sélectionne l’action.','Ligne 2 : reconnaît voirCategories.','Ligne 3 : prépare les données.','Ligne 4 : charge la vue.','Ligne 5 : termine le cas.','Ligne 6 : ferme le switch.'],'La vue doit recevoir les catégories avant d’être chargée.',['Oublier break.','Appeler la vue avant le modèle.'],['Le bon cas est sélectionné.','Les données sont stockées.','La vue est chargée puis break quitte le cas.'])
C(4,29,'Modification','Dans une action de modification, lis REQUEST produit dans $idProduit, récupère le produit et les catégories via $laConnexion puis inclus vues/v_modif_produit.php.','$idProduit = $_REQUEST["produit"];\n$leProduit = $laConnexion->getLeProduit($idProduit);\n$lesCategories = $laConnexion->getLesCategories();\ninclude("vues/v_modif_produit.php");',['Ligne 1 : identifie le produit reçu.','Ligne 2 : récupère ses informations.','Ligne 3 : prépare les catégories du formulaire.','Ligne 4 : appelle la vue de modification.'],'Deux jeux de données sont nécessaires à cette vue.',['Passer une catégorie à getLeProduit.','Oublier la liste des catégories.'],['L’identifiant provient de produit.','Produit et catégories sont récupérés.','La vue de modification est appelée ensuite.'],context='Le paramètre produit est présent ; $laConnexion expose les méthodes du cours.')
C(4,[43,48],'Films','Le modèle est dans $modele. Pour l’action de liste, conserve obtenirLesFilms() dans $films puis inclus vues/liste_films.php.','$films = $modele->obtenirLesFilms();\ninclude("vues/liste_films.php");',['Ligne 1 : demande la collection au modèle.','Ligne 2 : présente la liste.'],'L’appel du modèle précède l’inclusion.',['Utiliser obtenirUnFilm sans identifiant.','Insérer du SQL dans la vue.'],['La méthode de liste est utilisée.','Les films sont stockés dans $films.','La vue liste_films est incluse.'],'facile')
C(4,[43,46,48],'Films','L’id du film est déjà dans $id. Récupère le film avec $modele->obtenirUnFilm($id) dans $film puis inclus vues/details_film.php.','$film = $modele->obtenirUnFilm($id);\ninclude("vues/details_film.php");',['Ligne 1 : lit l’occurrence sélectionnée.','Ligne 2 : affiche sa vue de détail.'],'La lecture cible un identifiant de film.',['Utiliser la liste complète à la place du film.','Oublier de transmettre l’id.'],['Le bon id est transmis.','Le résultat est dans $film.','La vue de détail est incluse.'],'facile')
C(4,[43,48],'Films','$idCategorie est défini. Lis les films de cette catégorie dans $films avec $modele puis inclus vues/liste_films.php.','$films = $modele->obtenirFilmsParCategorie($idCategorie);\ninclude("vues/liste_films.php");',['Ligne 1 : filtre les données via le modèle.','Ligne 2 : réutilise la vue de liste.'],'Une même vue peut afficher une liste filtrée.',['Passer l’id à obtenirUnFilm.','Filtrer uniquement visuellement sans demander la bonne collection.'],['Le filtre utilise la méthode par catégorie.','L’idCategorie est transmis.','La liste filtrée est fournie à la vue.'])
C(4,[47,48],'Ajout films','Les données sont déjà récupérées et validées dans $donnees. Appelle ajouterFilm sur $modele puis récupère la nouvelle liste dans $films et inclus sa vue. Pas de redirection HTTP demandée.','$modele->ajouterFilm($donnees);\n$films = $modele->obtenirLesFilms();\ninclude("vues/liste_films.php");',['Ligne 1 : demande l’insertion au modèle.','Ligne 2 : recharge les données après cet ajout.','Ligne 3 : présente la liste actualisée.'],'Il faut relire la collection après l’insertion.',['Afficher une ancienne liste non actualisée.','Réaliser INSERT dans la vue.'],['Le modèle reçoit les données validées.','La collection est relue après l’ajout.','La vue affiche cette nouvelle collection.'],context='Variante courte du parcours d’enregistrement ; le support demande aussi un retour vers la liste.')
C(4,49,'Point d’entrée','Dans le catalogue, récupère GET controleur dans $controleur avec défaut "films", puis GET action dans $action avec défaut "liste".','$controleur = $_GET["controleur"] ?? "films";\n$action = $_GET["action"] ?? "liste";',['Ligne 1 : choisit le sous-contrôleur avec défaut.','Ligne 2 : choisit sa fonctionnalité avec défaut.'],'Les deux paramètres ont des rôles distincts.',['Inverser films et liste.','Lire seulement l’action sans prévoir de défaut.'],['controleur est récupéré.','action est récupérée.','Les défauts sont films et liste.'],'facile')
import runpy
runpy.run_path(str(D/'editorial.py'))['apply'](banks)

if __name__=='__main__':
 for ch,items in banks.items():
  assert sum(q['type']!='code' for q in items)==50
  assert sum(q['type']=='code' for q in items)==15
  (D/f'chapitre-{ch}.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
 print('Banque produite : 200 QCM et 60 exercices, 260 identifiants uniques.')
